/**
 * A história de cada NPC do Codex, em prosa, para a ficha pública.
 *
 * O Codex derivado das Casas carrega uma linha de descrição por figura, o que
 * deixa a ficha vaga demais para servir de leitura. Estas biografias são
 * autoradas sobre esse cânone: nunca o contradizem, apenas o desdobram em
 * origem, feridas, laços e a posição de cada um na crise atual.
 *
 * A chave é `${affiliation}:${id}`, a mesma que `fullCodex` usa para desempate
 * — só o id colidiria entre Casas.
 *
 * Personagens que jogadores adicionaram pelo Adicionar Canônico não entram
 * aqui: eles não passam pelo Codex, e o texto deles é do jogador.
 */
export const NPC_BIOGRAPHIES: Record<string, string> = {
  "casa-auremont:alena-primeira-espiga":
    "Alena Primeira-Espiga nasceu em aldeia de canal, numa família de arrendatários que guardava sementes em potes de barro marcados com riscos de faca. O sobrenome veio depois, quando ela levou ao solar uma espiga torta da primeira colheita de uma vila endividada e exigiu que fosse colocada ao lado do feixe cerimonial. O episódio correu pelos Campos Dourados, repetido nas cozinhas como afronta e nas aldeias como justiça.\n\nSua presença em Aurivale não veio por favor nobre, mas por pressão de moleiros, pequenos proprietários e trabalhadores sazonais que já não aceitavam falar apenas por petições. Isolde a recebe com cortesia medida. Marcien responde às suas acusações com ironia de cavalaria. Celestine de Vaux traz livros para desarmá-la; Remy Hal oferece contas e às vezes ouve mais do que admite. Alena conhece os nomes dos vilarejos onde esses números viram panela vazia.\n\nCostuma prender o cabelo com uma tira de pano tingida em açafrão, visível mesmo no salão mais dourado. O povo a segue nas feiras e repete suas frases sem pedir licença. Na crise atual, permanece entre aldeias e palácio, levando rumores de requisição, fofocas sobre preços e listas de famílias que não aparecem nos banquetes.",
  "casa-auremont:dama-celestine-de-vaux":
    "Dama Celestine de Vaux veio de uma família menor dos Campos Dourados, proprietária de moinhos e de um arquivo tão organizado que antigos cobradores da Coroa ainda o citam com irritação. Na juventude, viu uma praga de umidade arruinar sacos inteiros de cevada em depósito nobre, episódio que a tornou conhecida por mandar abrir paredes, trocar madeiras e demitir parentes de gente importante sem alterar o tom de voz. Quando Aurivale precisou de uma Mestra dos Celeiros, Isolde escolheu a mulher que tratava grão como documento selado.\n\nSeu cargo a colocou no centro das tensões da Casa. Marcien respeita seus números, embora reclame da lentidão com que ela libera carroças. Remy Hal disputa com ela cada coluna de dízimo. Alena Primeira-Espiga a enfrenta nos pátios quando aldeias dizem que a medida oficial encolhe no caminho. Celestine responde com recibos, selos e inspeções surpresa.\n\nÉ lembrada pelo molho de chaves pendurado no antebraço, tão pesado que deixa marca na manga. Camponeses a chamam de Dama Tranca, com mais cautela do que riso. Na crise atual, percorre depósitos subterrâneos, tulhas de semente e rotas de canal, pois todos em Aurivale sabem que Asterhall pedirá números antes de pedir desculpas.",
  "casa-auremont:duquesa-isolde-auremont":
    "A Duquesa Isolde Auremont foi criada entre varandas de música, salas de mapas agrícolas e visitas de arrendatários que nunca chegavam ao mesmo corredor dos convidados nobres. Filha de um ramo antigo da Casa, ganhou reputação ainda jovem ao conduzir a Festa da Primeira Espiga durante uma safra irregular, quando mandou servir pão menor no salão principal para que ninguém esquecesse o tamanho real da colheita. O gesto foi comentado como humildade por uns e cálculo por outros.\n\nAssumiu Aurivale após anos de tutela administrativa, conhecendo canais, casamentos, dívidas rurais e a linguagem silenciosa dos banquetes. Marcien, seu herdeiro, recebe dela responsabilidades militares e respostas afiadas. Celestine de Vaux controla reservas que Isolde raramente menciona em voz alta. Remy Hal traz livros de dízimos à mesa da manhã. Alena Primeira-Espiga entra no palácio como lembrança viva de que os campos possuem gente, não apenas produção.\n\nSua presença é marcada por vestidos de tons claros e uma pequena tesoura de poda presa ao cinto, hábito que irrita cortesãos de Asterhall. O povo de Aurivale a respeita porque a cidade permanece abastecida, mas observa cada portão fechado. Na crise atual, Isolde recebe mensageiros da Coroa enquanto os celeiros subterrâneos viram assunto de oração, boato e contabilidade.",
  "casa-auremont:lorde-marcien-auremont":
    "Lorde Marcien Auremont nasceu nos aposentos voltados para os canais de Aurivale, filho da linhagem que mede prestígio em hectares, cavalos e promessas antigas. Desde menino acompanhou a Duquesa Isolde nas cerimônias da Primeira Espiga e aprendeu, com Dama Celestine de Vaux, que um celeiro mal contado podia pesar mais que uma derrota em campo. Sua formação terminou nos pátios de cavalaria, onde cavaleiros de Saint-Lys ainda contam como ele quebrou a clavícula num torneio e voltou à sela antes do curativo secar.\n\nChegou ao comando da cavalaria por sangue, mas conservou o posto por disciplina: inspeções ao amanhecer, listas de ferraduras, mapas de pontes e um desprezo visível por oficiais que tratam abastecimento como assunto menor. Em Aurivale, é o herdeiro que senta à mesa de Isolde sem baixar os olhos, discute números com Remy Hal e troca farpas frias com Alena Primeira-Espiga quando as aldeias exigem mais voz.\n\nO povo o chama de cervo de luvas negras, por causa das luvas de montaria que nunca tira em público. Na crise atual, permanece entre os estábulos nobres e o salão de grãos, preparando escoltas para comboios enquanto Asterhall fala em coroação antecipada e requisições.",
  "casa-auremont:padre-contador-remy-hal":
    "Remy Hal nasceu entre os registros da Ordem do Sino e as colheitas de Aurivale, filho de um sacristão que também media dízimos em aldeias de moinho. Aprendeu cedo que um nome escrito errado podia tirar pão de uma família ou entregar terras a um primo mais rico. Ordenou-se sem abandonar a aritmética, e ganhou o apelido de Padre-Contador depois de corrigir, diante de três testemunhas, a soma de um intendente Auremont durante uma coleta de inverno.\n\nIsolde o chamou para cuidar de dízimos e reservas quando as contas da Casa já exigiam alguém capaz de ler pecado, safra e juros na mesma página. Remy trabalha perto de Celestine de Vaux, embora os dois discutam sobre perdas, caridade e grão reservado para semente. Marcien o considera útil e aborrecido. Alena Primeira-Espiga o acusa de transformar suor camponês em linhas limpas demais.\n\nUsa batina simples, dedos manchados de tinta e um ábaco de osso que bate como rosário nas audiências. Entre o povo, sua fama oscila entre homem justo e cobrador de batina. Na crise atual, ocupa uma sala estreita no solar de Aurivale, comparando dízimos atrasados, listas de refugiados e pedidos da Coroa que chegam com selo urgente.",
  "casa-do-ouro:capitao-jorren-daal":
    "Jorren Daal veio das escoltas de estrada, não das mesas de contrato. Filho de uma família de guardas pagos por caravanas, conheceu a Estrada das Brumas quando ainda carregava lanças maiores que o próprio braço. Sua fama nasceu num ataque de salteadores perto de Raven's Cross, quando manteve três carroças de prata em círculo até reforços chegarem. A Casa do Ouro comprou sua dívida de soldado, pagou seu tratamento e depois lhe entregou homens melhores do que os que ele comandava antes.\n\nComo capitão das escoltas, Jorren protege moedas, pessoas e papéis que valem mais que muitas fortalezas. O Príncipe Sétimo aprecia sua franqueza medida. Liora Venn exige recibos até de ferraduras. Ortiz informa quais tabernas ouvir antes de escolher rota. Seressa Nove-Contas pressiona por contratos mais arriscados, e Jorren responde mostrando mapas manchados de chuva. Irmão Calven recorre a ele quando funerais nobres precisam de guardas discretos.\n\nTem barba grisalha aparada curta e uma velha fivela amassada que se recusa a trocar. Nos cais, é visto como homem duro, mas menos cruel que mercenários comuns. Na crise atual, organiza comboios entre Porto Cinzento, Asterhall e Aurivale, enquanto cada estrada parece carregar tanto refugiados quanto oportunidades de emboscada.",
  "casa-do-ouro:dama-seressa-nove-contas":
    "Dama Seressa Nove-Contas pertence a um dos ramos mais falados da Casa do Ouro, conhecido por comprar riscos que outros ramos preferem registrar e esquecer. A alcunha veio de uma audiência juvenil em que ela refez nove vezes a mesma proposta até transformar uma perda provável em participação lucrativa num estaleiro falido. Desde então, sua assinatura passou a aparecer em seguros de navio, fornecimento militar e sociedades que ninguém na Casa comenta durante jantares formais.\n\nLíder de ramo, Seressa vive em atrito elegante com o centro de Setecofres. O Príncipe Sétimo a recebe porque não pode ignorar seus credores. Liora Venn corta suas cláusulas com prazer visível. Ortiz mede as palavras perto dela. Jorren Daal desconfia de suas rotas urgentes, e Irmão Calven já precisou desfazer heranças que seus aliados deixaram embaraçadas.\n\nSeressa usa nove contas de ouro costuradas no punho esquerdo, uma para cada cálculo que, segundo ela, salvou seu nome. O povo de Porto Cinzento a vê como patrona de oportunidades perigosas: paga rápido, cobra mais rápido ainda. Na crise atual, frequenta leilões de armas, cais lotados e reuniões sobre financiamento da guerra, onde sua risada costuma preceder propostas que fazem os prudentes perderem o sono.",
  "casa-do-ouro:irmao-calven":
    "Irmão Calven foi entregue jovem à Ordem do Sino, mas nunca deixou de pertencer à órbita da Casa do Ouro. Vinha de parentes pobres de um ramo colateral, gente que conhecia a diferença entre nascer com nome e nascer com recibo. Nos arquivos funerários da Abadia Branca, destacou-se ao resolver uma disputa em que três viúvas apresentavam documentos verdadeiros e incompletos. A decisão evitou duelo, falência e escândalo, e Setecofres passou a requisitá-lo sempre que sangue e contrato se misturavam.\n\nComo representante junto à Ordem do Sino, Calven transita entre cemitérios, cartórios e cofres. O Príncipe Sétimo valoriza sua leitura de legitimidade. Liora Venn lhe envia testamentos com margens anotadas. Ortiz entrega nomes sussurrados em velórios. Seressa Nove-Contas considera sua cautela inconveniente. Jorren Daal fornece escolta quando registros precisam atravessar estrada hostil.\n\nCalven fala baixo e carrega um sinete sem ornamento, preso ao pescoço por cordão escuro. Entre famílias endividadas, é temido porque sabe qual filho tem direito a quê. Entre religiosos, é respeitado por não brincar com nomes dos mortos. Na crise atual, acompanha rumores de sucessão, mortos que inquietam o Norte e contratos que dependem de provar quem ainda está vivo.",
  "casa-do-ouro:mestra-liora-venn":
    "Mestra Liora Venn nasceu num dos ramos administrativos da Casa do Ouro, gente sem grandes títulos, mas com autoridade sobre chaves, lacres e memória. Aos quinze anos, durante um incêndio em armazém segurado pela Casa, recusou liberar indenização antes de verificar as marcas de fuligem nos barris. Descobriu fraude, perdeu amigos no cais e ganhou lugar nos arquivos de Setecofres. A partir daí, sua carreira avançou menos por simpatia que por uma sequência de erros alheios encontrados a tempo.\n\nComo administradora dos cofres, Liora mantém distância calculada do luxo. O Príncipe Sétimo a trata como contrapeso necessário. Ortiz traz notícias que ela transforma em cláusulas. Jorren Daal reclama de seus cortes em escoltas caras. Seressa Nove-Contas a chama de freio enferrujado, em voz alta o bastante para ser ouvida. Irmão Calven sabe que nenhum testamento contestado passa por ela sem voltar marcado.\n\nUsa lentes presas por corrente fina e deixa selos quebrados em pequenos pratos de cobre, para lembrar quem tentou apressar o procedimento. Comerciantes a temem porque ela escuta desculpas até o fim. Na crise atual, calcula o peso de empréstimos reais, contratos militares e garantias oferecidas por uma Coroa que ainda não sabe quanto a guerra custará.",
  "casa-do-ouro:ortiz":
    "Ortiz não nasceu nos salões de Setecofres. Surgiu, segundo a versão mais repetida em Porto Cinzento, entre carregadores de cais, cozinhas de hospedaria e mensageiros que sabiam atravessar uma sala sem serem lembrados depois. Entrou a serviço da Casa do Ouro como ajudante de inventário, mas ganhou atenção ao recuperar uma carta de crédito perdida antes que ela fosse apresentada por mãos erradas. Desde então, aprendeu a circular onde brasões chamariam atenção demais.\n\nHoje atua como agente e negociador, embora muitos nobres ainda prefiram chamá-lo de servo. O Príncipe Sétimo o escuta em particular. Liora Venn confere suas informações antes de abrir qualquer cofre. Jorren Daal confia nele para avaliar rotas de escolta. Seressa Nove-Contas tenta arrancar dele nomes de capitães e credores; Irmão Calven o usa em disputas de herança quando testemunhas desaparecem convenientemente.\n\nOrtiz tem o hábito de limpar as unhas com a ponta de uma pena quebrada, mesmo em salas impecáveis. Entre estivadores, é tratado como alguém que paga em dia. Entre nobres, como uma sombra mal posicionada. Na crise atual, percorre Porto Cinzento e Asterhall reunindo rumores sobre grão, guerra e votos, sempre chegando antes da versão oficial.",
  "casa-do-ouro:principe-setimo":
    "O Príncipe Sétimo do Ouro nasceu em Setecofres, mas sua juventude foi passada fora das salas de mármore. A tradição da Casa o enviou incógnito por caravanas, armazéns e audiências de contrato, onde aprendeu a reconhecer o som de uma promessa fraca antes mesmo da assinatura. Cronistas de Porto Cinzento dizem que sua primeira decisão pública foi adiar um empréstimo a um ramo aparentado, não por falta de moeda, mas por falta de testemunhas confiáveis. O gesto o tornou impopular por uma estação e respeitado por muitos anos.\n\nEscolhido pelos sete ramos, pelos credores e pelos administradores, assumiu o título com a paciência de quem conhece a idade das dívidas. Ortiz leva-lhe notícias que não entram nos livros. Mestra Liora Venn corrige seus cálculos com tinta vermelha. Dama Seressa Nove-Contas tenta puxar a Casa para apostas mais ousadas, enquanto Irmão Calven lembra que heranças mal registradas podem arruinar uma geração inteira.\n\nSua elegância é famosa: anéis discretos, roupas sem bordado inútil e uma bengala de madeira escura que toca o chão antes de cada resposta. Entre o povo, é visto como salvador de comboios e cobrador sem rosto. Na crise, negocia em Porto Cinzento e Asterhall, onde cada pedido de guerra chega com juros políticos.",
  "casa-drakorys:damaros-drakorys":
    "Damaros Drakorys pertence a uma linhagem que cresceu à sombra do Monte Aion e das histórias da Guerra dos Céus de Bronze. Quando jovem, serviu nas Três Enseadas, dormiu nos arsenais durante tempestades e carregou escudo nas procissões do Primeiro Fogo antes de receber assento entre veteranos. A cicatriz que lhe corta a crista esquerda vem de um exercício de formação, não de batalha gloriosa, e ele nunca permitiu que bardos a transformassem em lenda maior do que foi.\n\nComo Strategos da Escama, governa com o Conselho dos Escudos e repete que nenhum líder declara guerra sozinho. Sua autoridade, porém, pesa em cada debate. Ilyra das Cinzas cobra respeito aos ritos; Kassian Asa de Bronze exige atenção à frota; Myrra Escudo-Partido fere sua paciência com críticas públicas; Leônidas Sal-Negro traz números de grão que humilham discursos inflamados. Damaros escuta todos, quase sempre de pé, com as mãos fechadas atrás das costas.\n\nEm Akrathos, o povo o considera severo, justo no treinamento e lento em elogiar. Nas docas, dizem que ele conhece pelo nome mais escudos do que cortesãos. Na crise atual, pesa o Tratado do Mar de Bronze, a sucessão em Asterhall e a agitação em torno de Kaelen Drakorys sem oferecer certeza fácil aos emissários da Coroa.",
  "casa-drakorys:ilyra-das-cinzas":
    "Ilyra das Cinzas nasceu numa vila de encosta do Monte Aion, onde famílias draconatas recolhem cinza vulcânica para ritos domésticos e remédios amargos. Ainda criança, permaneceu imóvel durante uma procissão em que o vento apagou todas as lâmpadas menos a que ela carregava. O Templo do Primeiro Fogo registrou o episódio com sobriedade, mas o povo de Akrathos nunca foi sóbrio ao contá-lo. Anos de jejum, óleo, canto e estudo a levaram ao posto de sacerdotisa.\n\nNo Conselho dos Escudos, Ilyra representa a chama antiga diante de oficiais, artesãos e capitães. Damaros Drakorys escuta seus alertas mesmo quando discorda. Kassian Asa de Bronze pede bênçãos para navios, mas evita sermões longos. Myrra Escudo-Partido respeita sua coragem ritual. Leônidas Sal-Negro tenta traduzir suas exigências em custos possíveis. Com Kaelen Drakorys, sua presença tornou-se ainda mais observada, pois cada palavra sobre cinza e escama ganha ouvidos demais.\n\nIlyra usa a testa marcada por pó negro em forma de meia-lua e cheira a óleo queimado. O povo a reverencia, embora alguns jovens a considerem severa demais. Na crise atual, permanece no Templo do Primeiro Fogo, conduzindo vigílias por Krythos enquanto notícias de Asterhall chegam atravessadas pelo mar.",
  "casa-drakorys:kaelen-drakorys":
    "Kaelen Drakorys cresceu em Krythos entre cinza vulcânica, cânticos do Primeiro Fogo e histórias que os mais velhos contavam olhando para o mar em vez de para as crianças. Antes de ser chamada Donzela das Cinzas, era conhecida por acompanhar procissões descalça nos degraus quentes de Akrathos e por dividir comida com aprendizes de arsenal. As cicatrizes em forma de escama no rosto mudaram sua vida pública: para alguns, marca de bênção; para outros, sinal perigoso demais para ser discutido em voz alta.\n\nSua coroação como Rainha-Dragã não apagou o Conselho dos Escudos, mas mudou a temperatura de cada sala. Damaros Drakorys mede suas palavras diante dela. Ilyra das Cinzas vigia os ritos que seu nome atrai. Kassian Asa de Bronze ouve marinheiros repetirem suas visões nas docas. Myrra Escudo-Partido exige que fervor também carregue escudo. Leônidas Sal-Negro calcula o custo de multidões reunidas longe do trabalho.\n\nKaelen fala como profetisa e consola como irmã, alternando chama e ternura sem pedir passagem. Usa roupas simples com cinza costurada na gola, e muita gente tenta tocar a barra do manto. Na crise atual, permanece em Krythos, cercada por seguidores, dúvidas oficiais e mensageiros de Asterhall que não sabem se devem tratá-la como nobre, santa ou ameaça política.",
  "casa-drakorys:kassian-asa-de-bronze":
    "Kassian Asa de Bronze nasceu perto das enseadas militares de Krythos, filho de uma família de pilotos que conhecia correntes antes de conhecer genealogias. Entrou na marinha ainda jovem e ganhou o epíteto quando, durante uma tempestade, amarrou placas de bronze a um mastro partido para manter uma vela mínima até a baía. Marinheiros contam a história com exageros diferentes, mas todos concordam que ele chegou a Akrathos sem abandonar os barcos menores que o seguiam.\n\nComo almirante, Kassian comanda navios, fuzileiros e patrulhas do Estreito de Bronze. Damaros Drakorys aprecia sua popularidade e a vigia com atenção. Ilyra das Cinzas unge suas proas antes de campanhas. Myrra Escudo-Partido o provoca quando fala demais em glória naval. Leônidas Sal-Negro lembra que marinheiros também comem, e que Krythos compra grão fora. Kaelen Drakorys divide opiniões em suas tripulações, algumas tomadas por fervor, outras por disciplina antiga.\n\nKassian usa uma braçadeira de bronze polida apenas por água salgada e tem a voz rouca de quem gritou ordens contra vento. Pescadores o saúdam com respeito informal. No Conselho, seu carisma incomoda. Na crise atual, mantém a frota pronta entre Akrathos e as Três Enseadas, enquanto a Coroa pergunta por deveres navais e Krythos pergunta por respeito.",
  "casa-drakorys:leonidas-sal-negro":
    "Leônidas Sal-Negro nasceu numa família de administradores costeiros que lidava com salinas, barris de peixe e contas de importação de grão. O apelido veio do sal escurecido que restou após um incêndio em armazém de Akrathos. Enquanto outros discutiam culpa, ele separou o que ainda podia alimentar gente, registrou perdas e reorganizou entregas para três bairros. A ação o levou dos depósitos portuários aos celeiros e ao comércio da Casa Drakorys.\n\nNo Conselho dos Escudos, Leônidas fala depois dos guerreiros e antes que as decisões virem ordem impossível. Damaros Drakorys o consulta quando a honra precisa caber em navios de carga. Ilyra das Cinzas acusa seus cálculos de esquecerem oferendas, e ele responde reservando óleo antes que peçam. Kassian Asa de Bronze exige espaço para a frota. Myrra Escudo-Partido o chama de mercador de escamas, sem negar que ele costuma estar certo. A ascensão de Kaelen torna suas planilhas ainda mais disputadas.\n\nLeônidas tem dedos grossos, sempre com manchas de sal e tinta, e mastiga folhas amargas durante reuniões longas. O povo o respeita sem amá-lo, pois sabe que sua assinatura decide preços. Na crise atual, negocia grãos de Valdren, vigia estoques de Krythos e tenta manter Akrathos alimentada enquanto todos falam em fogo.",
  "casa-drakorys:myrra-escudo-partido":
    "Myrra Escudo-Partido veio de uma família comum de hoplitas, sem brasão antigo além de lanças bem cuidadas. Recebeu o nome que a tornou conhecida numa campanha de repressão a piratas, quando segurou uma passagem estreita com o escudo rachado ao meio e recusou substituição até a linha recuar inteira. Depois da baixa no serviço ativo, esperava-se que aceitasse uma cadeira tranquila de treinamento. Em vez disso, passou a comparecer a audiências do Conselho e fazer perguntas que deixavam escribas sem tinta suficiente.\n\nSua crítica ao Conselho dos Escudos é pública, áspera e difícil de descartar, pois vem de alguém que pagou o preço do serviço. Damaros Drakorys a suporta como se suporta uma pedra dentro da sandália durante marcha longa. Ilyra das Cinzas a trata com respeito ritual. Kassian Asa de Bronze ri de suas censuras até que alguma acerte o alvo. Leônidas Sal-Negro chama suas soluções de caras demais. Kaelen Drakorys encontra nela tanto admiração popular quanto resistência veterana.\n\nMyrra caminha com leve arrasto na perna direita e carrega um fragmento do antigo escudo preso ao cinto. O povo de Akrathos a chama para arbitrar brigas de quartel e disputas de pensão. Na crise atual, ocupa praças, arsenais e sessões abertas, perguntando quem servirá quando os discursos terminarem.",
  "casa-euralune:eldra-folhavento":
    "Eldra Folhavento pertence a uma linhagem de druidas que registrava nascimentos de águias muito antes de muitos nobres das terras baixas saberem apontar Ninho Alto no mapa. Nasceu em um vale suspenso onde jardins crescem em caixas de pedra e aprendeu os ritos do Pacto das Alturas ouvindo os mais velhos narrarem o inverno em que gnomos dividiram alimento com filhotes famintos. Sua formação pública foi marcada pela Praga da Pena Escura, uma doença local que atingiu ninhos menores; Eldra coordenou isolamento, ervas de altitude e vigílias até a primavera devolver voos ao céu.\n\nComo Grã-Druida, ela não governa, mas nenhuma decisão importante passa ilesa por sua voz. Brannic a consulta e a enfrenta; Lyra foi educada sob sua sombra; Tobren respeita seu conhecimento mesmo quando prefere soluções de corda e couro; Nessa a procura para levar queixas de aldeias ao salão. O povo a vê como guardiã de equilíbrio, não como santa dócil. Carrega sempre um cajado de zimbro envernizado, coberto por pequenas fitas com nomes de aves mortas. Na crise atual, Eldra permanece em Ninho Alto separando presságio de pânico, enquanto os ventos trazem notícias quebradas do Norte.",
  "casa-euralune:lorde-brannic-euralune":
    "Brannic nasceu no ramo alto dos Euralune, entre salões escavados no paredão de Ninho Alto e plataformas onde crianças aprendem o nome das correntes de vento antes das estradas do reino. Sua família servia aos conselhos das aldeias desde a época em que o Pacto das Alturas ainda era lembrado por cicatrizes de fome: velhos contam que um antepassado seu partilhou a própria ração com filhotes de águia durante o inverno que quase quebrou os ninhos. Brannic cresceu sob essa medida severa de valor, mais atento ao olhar das aves que ao brilho de selos nobres.\n\nChegou ao título de Senhor dos Ventos depois de anos como mediador entre aldeias, patrulheiros e druidas, quando uma sequência de deslizamentos isolou três comunidades e ele coordenou resgates sem esperar ordens de Asterhall. O povo das montanhas o chama de paciente; nobres das terras baixas, de insolente com boa caligrafia. Lyra, Tobren, Eldra, Pim e Nessa orbitam seu salão com respeito e atrito visível. Na crise atual, Brannic permanece em Ninho Alto, oferecendo olhos no céu, rotas e resgate, sempre com luvas de couro cinza e a mesma pausa longa antes de aceitar qualquer favor.",
  "casa-euralune:lyra-euralune":
    "Lyra Euralune, filha de Brannic, cresceu no lado mais exposto de Ninho Alto, onde o vento entra pelas frestas das salas e apaga velas mal protegidas. Desde pequena preferia acompanhar curandeiros e tratadores aos exercícios formais do conselho, e aprendeu com Eldra Folhavento a ler o humor das criaturas aladas pelo peso das penas, pela inclinação do pescoço e pelo silêncio antes do voo. O episódio que a marcou publicamente foi o resgate de um filhote de hipogrifo prateado preso abaixo da Ponte da Nuvem Partida; Lyra desceu amarrada por cordas de cânhamo enquanto aldeões gritavam contra a neve.\n\nAnos depois, o mesmo hipogrifo a aceitou, e a herdeira passou a ser vista como ponte viva entre o salão de Brannic e os druidas. Sua presença provoca afeto nas aldeias e discussões francas entre os mais duros dos patrulheiros, especialmente quando fala de pacto, comércio e terras baixas. Tobren respeita sua mão leve com montarias; Pim a escolta sem reclamar; Nessa a cobra sem cerimônia. Na crise atual, Lyra permanece em Ninho Alto auxiliando resgates e mensagens, reconhecível pelo manto de lã clara sempre salpicado de penas prateadas.",
  "casa-euralune:nessa-tres-sementes":
    "Nessa Três-Sementes nasceu numa das comunidades baixas dos Picos, onde a terra cultivável cabe em terraços estreitos e cada saco de grão tem nome, dono e história. O apelido veio de uma infância contada em fome: diz-se que ela guardou três sementes de cevada durante um inverno ruim e as plantou na primavera, recusando-se a entregá-las a quem chamava aquilo de gesto inútil. A anedota cresceu porque Nessa também cresceu assim, transformando pequenas reservas em argumento político e lembrando aos salões altos que liberdade sem comida vira palavra bonita.\n\nChegou a representante das aldeias pobres depois de organizar uma comitiva que subiu a Ninho Alto com listas de pontes quebradas, famílias desalojadas e tributos pagos em ervas raras. Brannic a recebe com formalidade; Lyra a escuta com atenção; Eldra já mediou mais de uma disputa entre ela e patrulheiros; Pim conhece suas críticas pelo nome. O povo a respeita por falar como quem carrega cestos, não brasões. Usa lenços remendados com linhas coloridas, cada cor indicando uma aldeia visitada. Na crise atual, Nessa reúne pedidos de abrigo e alimento enquanto a ilha fala de guerra e os pobres perguntam quem contará suas perdas.",
  "casa-euralune:pim-racha-nuvem":
    "Pim ganhou o nome Racha-Nuvem depois de conduzir uma patrulha por uma fenda de tempestade que os mapas de Ninho Alto marcavam como impraticável. Antes disso, era apenas o filho esperto de uma família de pontes, criado entre cordas, sinos de aviso e histórias de caravanas vistas lá embaixo como formigas carregando metal. Aprendeu cedo que os Picos da Nuvem Eterna não são defendidos por muralhas, mas por olhos atentos, pernas firmes e gente capaz de aparecer onde nenhum invasor espera resistência.\n\nSua ascensão a líder dos patrulheiros veio após uma série de ataques contra aldeias isoladas por saqueadores de vale. Pim reorganizou sentinelas, criou sinais de espelho entre plataformas e insistiu em patrulhas menores, rápidas e difíceis de rastrear. Brannic aprecia sua coragem, embora o salão conheça discussões entre ambos; Tobren cobra dele cuidado com aves cansadas; Lyra o convence a levar curandeiros; Nessa o acusa de lembrar tarde demais das aldeias pobres. Entre o povo, Pim é herói de taverna e dor de cabeça de conselheiro. Usa uma echarpe vermelha para ser visto na neve. Na crise atual, vigia passagens e mensagens, com a faca sempre presa ao antebraço esquerdo.",
  "casa-euralune:tobren-penhasco":
    "Tobren nasceu numa aldeia agarrada a uma parede de granito, filha de mineradores de ervas e guias de neve, e herdou o nome Penhasco antes de merecê-lo. Ainda jovem, perdeu dois dedos para o bico de uma águia ferida que tentava salvar; em vez de abandonar os ninhos, voltou no dia seguinte com a mão enfaixada e comida fresca. A história correu por Ninho Alto porque resume sua reputação: homem de poucas palavras, mais disposto a consertar sela, osso ou plataforma que a explicar seus sentimentos a um salão cheio.\n\nTornou-se Mestre das Águias após uma temporada de ventos ruins, quando reorganizou poleiros, rotas de alimentação e turnos de repouso, reduzindo acidentes entre montarias e cavaleiros. Brannic o escuta em assuntos de voo, ainda que ambos discordem diante de patrulhas mais ousadas. Lyra encontra nele um instrutor severo; Eldra o chama quando uma ave recusa toque humano; Pim depende de sua avaliação antes de lançar patrulhas longas. Entre aldeões, Tobren é tratado quase como ferreiro de asas. Na crise atual, permanece nos estábulos altos de Ninho Alto, cheirando a couro molhado, óleo de sela e neve, preparando aves para missões que talvez não admitam retorno rápido.",
  "casa-ferrumor:almirante-caelor-ventobranco":
    "Caelor Ventobranco nasceu numa família de pilotos costeiros da Costa das Agulhas, gente acostumada a medir perigo pelo som das ondas contra pedra invisível. Entrou jovem nos navios de Ferrumor e fez nome durante a Tempestade das Sete Lanternas, quando conduziu três embarcações de volta ao Porto Profundo depois que faróis menores falharam na lua nova. A proeza não virou canção delicada: marinheiros ainda contam que Caelor quebrou o próprio nariz contra o leme e continuou dando ordens com sangue na barba.\n\nA promoção a comandante da frota veio por competência acumulada, não por gentileza. Aedran valoriza sua experiência, embora os dois sustentem diferenças públicas sobre ritmo, risco e prestígio naval. Miriel transforma relatórios dele em argumentos; Sarya discute dimensões de docas e cascos; Teren o irrita com mapas antigos que nem sempre aceitam ventos modernos. Entre tripulações, Caelor é duro, justo e incapaz de tolerar cordame mal enrolado. Usa um casaco azul desbotado que recusa substituir, remendado nos punhos por mãos de marinheiros diferentes. Na crise atual, mantém navios prontos em Ferrum, atento a Brumas, comboios de grão e ordens vindas de uma Coroa apressada.",
  "casa-ferrumor:lady-miriel-ferrumor":
    "Miriel Ferrumor vem de uma linhagem criada para transformar memória em argumento. Na infância, em Ferrum, aprendeu genealogias de Caladris antes de aprender a calcular marés, e foi educada entre a Torre do Horizonte Perdido, os salões do Conselho das Nove Chaves e os cais onde trabalhadores estrangeiros lembram diariamente que a cidade é maior que suas famílias antigas. A primeira fama pública veio durante a greve dos carregadores do Porto Profundo: Miriel ouviu capitães, artífices e estivadores por três dias, depois redigiu um acordo que salvou uma encomenda real e deixou todos convencidos de que haviam vencido algo.\n\nDesde então, tornou-se a principal voz diplomática de Ferrumor. Aedran confia nela para dar forma aceitável ao orgulho da Casa; Caelor a acusa, em público moderado, de medir tempestades com pergaminhos; Sarya a procura quando uma obra precisa de patronos; Teren lhe fornece precedentes antigos que ela usa como lâminas polidas. Entre o povo, Miriel é admirada pela elegância e criticada por nunca parecer surpresa. Costuma usar um broche de bronze escuro em forma de sino caladriano. Com o Norte em silêncio, permanece em Ferrum negociando aço, navios e favores de Coroa como quem sabe que cada palavra também constrói um porto.",
  "casa-ferrumor:lorde-aedran-ferrumor":
    "Aedran Ferrumor foi criado entre o ruído das Grandes Forjas e o silêncio anual em que Ferrum apaga o fogo para ouvir o mar. Descendente das antigas famílias caladrianas, recebeu educação de navegador, engenheiro e juiz de contratos, porque um Alto Senhor de Ferrum precisa compreender tanto o peso de uma viga quanto a vaidade de um capitão. O episódio que o fixou na memória pública ocorreu quando uma tempestade arrancou parte dos guindastes do Porto Profundo; Aedran permaneceu nos terraços inferiores, coordenando reparos e evacuações enquanto sinos de bronze escuro chamavam equipes de emergência.\n\nComo chefe da Casa, governa ao lado do Conselho das Nove Chaves, equilibrando tradição, comércio e a pressão de uma cidade que precisa ser alimentada por fora. Miriel dá voz diplomática às suas posições, Caelor guarda a frota, Sarya ergue as obras que projetam seu nome, e Teren alimenta o passado que sustenta a Casa. Ferreiros o chamam de sereno; jovens oficiais, de lento; rivais khazdrun, de monumental demais. Costuma usar roupas escuras sem adorno, exceto um anel feito de aço negro. Na crise atual, Aedran permanece em Ferrum preparando navios, engenheiros e termos para qualquer convocação real.",
  "casa-ferrumor:mestra-sarya-arco-de-pedra":
    "Sarya Arco-de-Pedra não nasceu entre os salões mais antigos de Ferrumor, mas entre pedreiras altas onde a poeira branca gruda na pele e cada criança aprende a não passar sob carga suspensa. O sobrenome veio de sua primeira obra reconhecida: um arco de contenção erguido às pressas após um deslizamento fechar a estrada elevada entre as forjas e os depósitos de carvão. O arco ainda está de pé, manchado de fuligem, e trabalhadores batem nele com os nós dos dedos ao passar, como se cumprimentassem a própria mestra.\n\nSua ascensão à chefia das grandes obras aconteceu quando o Conselho das Nove Chaves precisou de alguém capaz de unir estética caladriana, cálculo hidráulico e pressa militar. Aedran a promoveu; Miriel usa seus projetos para impressionar clientes; Caelor reclama quando docas ficam belas demais e práticas de menos; Teren oferece desenhos antigos que Sarya redesenha sem reverência excessiva. Conservadores murmuram que ela muda Ferrum rápido demais, enquanto aprendizes a seguem com olhos acesos. Usa carvão preso atrás da orelha mesmo em audiências formais. Na crise atual, supervisiona reforços em pontes, guindastes e máquinas de cerco, pois uma guerra distante sempre começa exigindo estradas que aguentem peso.",
  "casa-ferrumor:teren-caladrin":
    "Teren Caladrin descende de uma família de escribas ligados à Chave da Memória, gente que preservou nomes de navios, medidas de torres e lamentos de refugiados desde a chegada dos sobreviventes de Caladris. Quando menino, foi encontrado várias vezes dormindo nos degraus da Torre do Horizonte Perdido, enrolado em mapas maiores que seu corpo. A história que o tornou conhecido entre estudiosos veio de uma maré excepcionalmente baixa: Teren identificou inscrições numa ilhota submersa da Costa das Agulhas e demonstrou que pertenciam a um sistema de faróis anterior à fundação de Ferrum.\n\nHoje é historiador da Casa, consultado por Aedran quando tradição precisa de precisão e por Miriel quando um tratado exige raízes antigas. Caelor o trata como homem útil demais para ser deixado sozinho no convés; Sarya aproveita seus achados, mas corta excessos ornamentais sem pedir desculpa. O povo o considera excêntrico e respeitável, sempre coberto de sal, tinta e poeira de arquivo. Tem o hábito de tocar três vezes a pedra antes de entrar na Torre, gesto que alguns imitam por superstição. Na crise atual, Teren compara relatos do Norte, Brumas e ruínas, procurando precedentes públicos em arquivos que raramente oferecem respostas limpas.",
  "casa-karasoy:aylin-karasoy":
    "Aylin Karasoy nasceu em Ordu-Yildiz quando a cidade móvel estava acampada sob céu limpo, perto das bordas de Sar-Khal. Sua família pertence às linhagens que guardam a Memória dos Caminhos, mas sua autoridade não veio apenas do sangue: veio de atravessar rotas difíceis, reconhecer água pelo cheiro do solo e manter carroças, cavalos e crianças em movimento quando as planícies negavam abrigo. As canções de sua juventude recordam a Marcha dos Cascos Vazios e as cercas que mataram montarias; Aylin cresceu ouvindo que mapa algum substitui a lembrança de quem perdeu sede na estrada.\n\nFoi reconhecida como Mãe da Planície após conduzir Ordu-Yildiz para fora de uma emboscada de salteadores, formando círculos de carroças durante a noite e abrindo caminho ao amanhecer com as Ak-Boran na frente. Selma comanda lanças em seu nome, Yasemin guarda os cavalos Tempestade Branca, Nahla pesa tradições, Leyla abre rotas e Derya mantém Sar-Khal presente nas decisões. O povo a respeita pela firmeza seca; mercadores a acham cara; a Coroa encontra nela uma lealdade que pede recibo. Na crise atual, Aylin está entre Ordu-Yildiz e as estradas reais, com tranças presas por anéis de mitril fosco e os olhos sempre voltados ao próximo horizonte.",
  "casa-karasoy:derya-sar-khal":
    "Derya Sar-Khal carrega no próprio nome a cidade abandonada que ainda pesa sobre a Casa Karasoy. Descende de guardiões das ruínas e foi criada ouvindo que pedra caída também fala, desde que alguém saiba sentar no silêncio certo. Quando jovem, encontrou sob areia e capim os restos de uma oficina antiga, com marcas de ferramentas anteriores à migração definitiva para as planícies. A descoberta não mudou mapas do reino, mas mudou seu lugar em Ordu-Yildiz: Derya passou a acompanhar expedições, catalogar objetos, corrigir lendas apressadas e lembrar que a Casa nasceu de perda, adaptação e escolha.\n\nO título antigo de Guardião das Ruínas Antigas lhe dá autoridade singular nos conselhos, especialmente quando mitril, rotas e memória entram na mesma conversa. Aylin a consulta antes de permitir escavações; Nahla respeita sua paciência; Leyla a considera útil e difícil; Selma reclama quando uma pedra velha atrasa cavaleiras; Yasemin preserva artefatos encontrados junto aos estábulos móveis. Entre o povo, Derya é vista como guardiã de coisas que ninguém deve vender por pressa. Usa luvas finas mesmo no calor, para tocar fragmentos sem gordura de pele. Na crise atual, permanece entre Ordu-Yildiz e Sar-Khal, vigiando rumores de guerra que transformam todo metal em promessa perigosa.",
  "casa-karasoy:leyla-duas-rotas":
    "Leyla recebeu o nome Duas-Rotas depois de retornar de uma missão de exploração com dois caminhos seguros onde os mapas marcavam apenas uma ravina sem água. Nasceu entre famílias de batedoras e comerciantes menores, gente acostumada a negociar passagem, observar poeira no horizonte e dormir com botas prontas. O evento que a formou foi o desaparecimento de uma caravana durante uma tempestade seca; Leyla, ainda aprendiz, seguiu marcas quase apagadas de roda, encontrou sobreviventes junto a uma depressão de argila e passou a defender treinamento menos dependente de fórmulas antigas.\n\nHoje é Mestra das Exploradoras, responsável por formar olhos e ouvidos da Casa antes que Selma mova lanças ou Aylin mova a cidade. Yasemin testa com ela resistência das montarias; Nahla corrige sua pressa com memórias; Derya fornece nomes antigos de ruínas que Leyla prefere transformar em pontos de referência; Aylin escuta seus relatórios com atenção curta e perguntas longas. Entre jovens, Leyla é admirada por aceitar aprendizes de famílias menos prestigiadas; entre conservadores, é vista como vento que entra por fresta. Carrega dois mapas costurados no forro do casaco. Na crise atual, percorre as bordas das estradas reais, medindo riscos para mensageiros e escoltas Karasoy.",
  "casa-karasoy:nahla-altunay":
    "Nahla Altunay tem oitenta e dois anos e carrega no corpo a história recente das Planícies da Estrela: joelhos de quem desmontou em terreno duro, mãos marcadas por rédeas e olhos ainda capazes de encontrar o norte sem olhar para o céu. Nasceu quando Ordu-Yildiz se reunia com menos carroças e mais postos contra vizinhos armados. Sua formação pública veio na Estação das Barragens, quando proprietários e chuvas ruins alteraram rotas de água; Nahla memorizou poços esquecidos, desviou famílias e manteve registros orais que depois se tornaram parte da Memória dos Caminhos.\n\nComo Guardiã da Estrela, é voz de experiência nos conselhos de Aylin e figura diante da qual jovens líderes medem palavras. Selma se impacienta com suas advertências, mas raramente as ignora; Yasemin preserva linhagens de cavalo que Nahla recita de memória; Leyla discute métodos novos sob seu olhar estreito; Derya encontra nela aliada quando Sar-Khal precisa ser lembrada. O povo a respeita como avó severa de uma cidade inteira. Usa contas de vidro azul nos cabelos, cada uma associada a uma rota antiga. Na crise atual, Nahla permanece em Ordu-Yildiz avaliando presságios públicos, mapas de vento e o preço de deslocar gente demais para perto da Coroa.",
  "casa-karasoy:selma-karasoy":
    "Selma Karasoy nasceu entre as carroças externas de Ordu-Yildiz, onde as crianças acordam com relinchos e dormem ouvindo metal bater em couro. Pertence a um ramo guerreiro da Casa, formado para proteger a cidade móvel quando as rotas atravessam terras disputadas. Sua fama começou no Vau Seco, durante uma tentativa de roubo de mitril por mercenários sem bandeira: Selma reuniu cavaleiras dispersas, desmontou a primeira linha inimiga com lanças leves e manteve a retirada organizada até que as carroças fechassem o círculo. Desde então, seu nome é dito com respeito em estábulos e com cautela em tendas de conselho.\n\nComo Lança de Luz, comanda tropas rápidas e guarda a honra marcial de Aylin diante de aliados e curiosos. Aylin a utiliza como mão firme; Yasemin garante que suas montarias estejam prontas; Nahla cobra respeito aos ritos; Leyla testa suas formações em terreno ruim; Derya lembra que Sar-Khal caiu quando promessas militares foram mal pesadas. O povo admira Selma pela presença feroz e pela disciplina com jovens cavaleiras. Usa uma lança de haste clara marcada por fitas de campanhas. Na crise atual, treina escoltas para as estradas reais e observa cada convocação com a paciência tensa de quem conta cascos.",
  "casa-karasoy:yasemin-altunay":
    "Yasemin Altunay vem de uma família conhecida por cuidar das Ak-Boran antes mesmo de ocupar assentos importantes nos conselhos de Ordu-Yildiz. Cresceu dormindo perto dos estábulos móveis, aprendendo que os cavalos Tempestade Branca respondem menos à força que à constância: voz igual, mãos limpas, comida oferecida sem pressa. O episódio que a tornou famosa aconteceu durante uma chuva de granizo nas Planícies da Estrela, quando um rebanho inteiro se dispersou rumo a terreno rachado. Yasemin cavalgou sem sela, guiou a égua-guia pelo vento e trouxe dezenas de animais de volta antes da noite.\n\nRecebeu o título de Domadora dos Ventos porque doma montarias e tempestades de gente com a mesma atenção quieta. Aylin a consulta antes de deslocar Ordu-Yildiz por longas distâncias; Selma depende de seus cavalos para qualquer carga; Nahla a elogia quando ela respeita linhagens antigas; Leyla a provoca com rotas que desafiam ferraduras; Derya registra os pedigrees como parte da memória da Casa. Entre o povo, Yasemin é querida por tratar potros e cavaleiras feridas com igual cuidado. Usa sempre um pente de osso preso ao cinto. Na crise atual, prepara montarias para mensageiros, escoltas e retirada, pois a cidade que cavalga sobrevive pela velocidade.",
  "casa-khazdrun:durgan-ferrosalto":
    "Durgan Ferrosalto veio de uma família de fundidores dos níveis médios de Khar-Durak, onde o calor das forjas secava a pele antes da infância acabar. Seu avô moldava dobradiças para portões de túnel; sua mãe afinava mecanismos de ventilação; Durgan ganhou nome quando um guindaste das Docas de Dentro partiu o eixo e ele improvisou um encaixe de ferro que segurou carga suficiente para salvar três cascos em reparo. Desde então, sua oficina atrai aprendizes que preferem ouvir broncas a trabalhar com ferramentas mal cuidadas.\n\nTornou-se Mestre de Ofício por voto dos clãs artesãos, não por simpatia. Ele conhece ligas, pressões e falhas antigas melhor que a maioria dos engenheiros que falam bonito diante do Conselho de Pedra. Essa autoridade o pôs em atrito com os estaleiros mais ousados e com capitães que pedem rapidez. Thrain o chama quando uma obra precisa durar gerações; Brynna escuta suas críticas com mais paciência do que ele demonstra merecer; Kaldrin o acusa de atrasar defesas; Eldra guarda os relatórios nos quais suas margens vêm cheias de correções.\n\nDurgan é baixo até para os padrões anões, tem sobrancelhas chamuscadas e usa o mesmo avental de couro remendado em reuniões formais. O povo o considera intratável, mas justo no preço e feroz contra material ruim. Na crise atual, percorre as rachaduras das minas batendo a pedra com um pequeno martelo de escuta, enquanto rumores sobre obras novas e antigas inflamam cada conversa de corredor.",
  "casa-khazdrun:eldra-oreluna":
    "Eldra Oreluna nasceu em uma família de lapidários de inscrição, gente que conhece a diferença entre decorar pedra e comprometer gerações. Ainda menina, memorizava marcas de clã nos elevadores e corrigia adultos quando um nome antigo era pronunciado errado. O episódio que a levou aos arquivos ocorreu após um desabamento menor nas Minas Antigas: Eldra encontrou, atrás de uma parede rompida, uma placa de manutenção esquecida que explicava a falha. A descoberta salvou uma equipe inteira de repetir o mesmo erro em outro túnel e convenceu o Conselho de Pedra a colocá-la entre os aprendizes de registro.\n\nComo arquivista, Eldra guarda atas, genealogias, contratos, mapas selados e listas de mortos que nenhuma família deseja ver mal copiadas. Thrain a consulta antes de prometer qualquer coisa que possa tocar autonomia antiga; Brynna recebe dela lições de precedente; Durgan discute datas de projeto como se duelasse; Kaldrin reclama que seus registros chegam sempre no momento menos conveniente. Eldra raramente levanta a voz, mas uma correção sua pode calar um salão.\n\nUsa lentes presas por corrente de prata e cheira a pó de ardósia, cera e chá amargo. Entre o povo, é respeitada como memória viva e temida como alguém que lembra inclusive o que foi dito em voz baixa. Agora, com rachaduras novas e alianças antigas pesando sobre a votação da Coroa, Eldra permanece nos arquivos de Khar-Durak, onde cada batida subterrânea parece pedir uma página correspondente.",
  "casa-khazdrun:kaldrin-marebrava":
    "Kaldrin Marébrava nasceu entre famílias costeiras ligadas aos Clãs da Maré, nos bairros onde crianças aprendem a nadar antes de ler marcas de família. Seu pai comandava uma torre de corrente no Portão das Marés; sua mãe mantinha registros de carga nas Docas de Dentro. Kaldrin ganhou fama quando piratas de enseada tentaram incendiar um estaleiro externo: ainda jovem, reuniu marinheiros, guardas de túnel e operários com ganchos de carga, fechando o cais até a infantaria chegar. A balada que surgiu depois exagera os golpes, mas não inventa sua presença.\n\nComo comandante dos Fuzileiros de Doca, ocupa um lugar desconfortável entre soldados, marinheiros e conselheiros que preferem conflitos por contrato. Ele fala bem com a tropa e mal com mesas longas. Thrain aprecia sua coragem, mas mede suas propostas com cuidado; Brynna enfrenta dele perguntas ásperas em público; Durgan resmunga que Kaldrin pede ferro como se minas crescessem ao grito; Eldra registra suas objeções sem suavizar verbo algum.\n\nKaldrin é lembrado pelo riso alto, pela barba presa em uma única trança grossa e pelo hábito de treinar com armadura molhada para simular combate em cais inundado. O povo das docas o trata como um dos seus, enquanto parte dos clãs de raiz o chama de maré sem comporta. Com as batidas nas profundezas e a política da Coroa atravessando Khar-Durak, ele mantém os fuzileiros nos portões, nas correntes e nas passagens que ligam mar e montanha.",
  "casa-khazdrun:lady-brynna-khazdrun":
    "Brynna Khazdrun nasceu nos Terraços do Vento, onde as janelas olham para a Baía do Martelo e o sal marca até as dobradiças. Filha mais velha de Thrain, foi educada por mestres de pedra, capitães de doca e arquivistas que não aceitavam respostas apressadas. Ainda adolescente, acompanhou uma inspeção às bombas das Forjas da Maré durante uma tempestade. Quando uma comporta emperrou e a água começou a subir, Brynna organizou aprendizes para mover correntes auxiliares até a equipe principal chegar. A história cresceu em versões diferentes, mas todos concordam que ela saiu dali com a voz rouca e as mãos queimadas de corda.\n\nSua posição de herdeira a coloca entre clãs que respeitam sangue, serviço e idade em medidas diferentes. Thrain a mantém perto das audiências para que todos se acostumem à sua presença. Durgan Ferrosalto corrige sua terminologia quando ela fala de forja; Kaldrin Marébrava testa sua paciência diante dos fuzileiros; Eldra Oreluna lhe entrega registros que muitos prefeririam resumidos.\n\nBrynna é reconhecida pelo cabelo preso em tranças curtas, sem joias pesadas, e pelo costume de anotar perguntas nas costas de placas de inventário. Entre artesãos jovens, é vista como alguém que escuta antes de decidir. Entre anciãos, ainda há silêncio demais depois de seu nome. Com as minas rachando e a Casa envolvida na votação da Coroa, ela permanece em Khar-Durak aprendendo em público, o que para uma Khazdrun pode ser mais duro que errar em segredo.",
  "casa-khazdrun:lorde-thrain-khazdrun":
    "Thrain Khazdrun nasceu nos Salões dos Clãs, filho de uma linhagem que gravava contratos antes de aprender a cantar. Seu pai administrava elevadores de minério, sua mãe vinha dos Clãs da Maré, e essa dupla origem o colocou cedo entre os corredores secos da raiz e as docas úmidas de dentro. Ainda jovem, sobreviveu ao colapso de uma galeria de prata nas Minas Antigas. Saiu coberto de pó cinzento, carregando nos braços o martelo quebrado do capataz, e desde então passou a ouvir relatórios de obra como outros ouvem confissões.\n\nChegou ao senhorio depois de anos no Conselho de Pedra, mediando disputas entre mestres de túnel, armadores e guardas de portão. Entre os Khazdrun, é visto como lorde de balança lenta: pesa cada palavra, cobra cada dívida e raramente esquece um favor. Brynna, sua herdeira, acompanha audiências ao seu lado; Durgan Ferrosalto o respeita, embora reclame das concessões aos estaleiros; Kaldrin Marébrava pressiona por respostas mais duras; Eldra Oreluna guarda as atas que ele consulta com frequência.\n\nO povo de Khar-Durak reconhece Thrain pela barba trançada com anéis de ferro escurecido e pelo hábito de tocar a parede antes de decidir. Com rachaduras nas minas e batidas nas profundezas, ele permanece entre o Portão das Marés e o conselho, oferecendo apoio à Coroa sem abrir mão das chaves da montanha.",
  "casa-rimerberg:capitao-orven-geada":
    "Orven Geada veio de uma família de caçadores das aldeias externas, acostumada a trocar peles por sal-gema e notícias de patrulha. Entrou para a guarnição depois que uma nevasca abriu um caminho antigo entre duas torres de sinal e levou três viajantes para fora da estrada marcada. Orven encontrou dois vivos, um morto e marcas que nenhum capitão conseguiu explicar sem baixar a voz. A partir daí, fez carreira nas patrulhas que caminham onde os mapas acabam, ganhando cicatrizes finas no rosto e uma reputação de voltar mesmo quando volta com menos gente do que levou.\n\nComo comandante das patrulhas externas, responde por batedores, cães de neve, depósitos escondidos e aldeias que Asterhall conhece apenas por nomes em listas. Ser Kael recebe seus relatórios com atenção tensa; Mestre Halm revisa suas leituras de gelo; Irmã Tessa cobra os corpos e os nomes que faltam; a ausência de Lady Ysabet tornou suas rotas do sul mais políticas do que militares. Orven não tem gosto por salão, mas sabe que cada saco de grão depende de alguém falando por ele.\n\nÉ alto, de voz baixa, e usa no cinto uma fileira de apitos de osso para sinais em neblina. Entre os aldeões, é considerado duro, porém presente. Entre nobres, direto demais. Com o Farol de Gelo apagado e refugiados descendo para Stonebridge, Orven se mantém nas bordas de Rimewatch, onde a neve apaga pegadas antes de apagar responsabilidades.",
  "casa-rimerberg:irma-tessa-do-ultimo-sino":
    "Tessa do Último Sino nasceu em uma casa de madeira próxima à capela de Rimewatch, neta de coveiros que conheciam o solo congelado melhor que muitos pedreiros. Foi entregue à Ordem do Sino depois de uma febre que matou metade das crianças de sua aldeia. A jovem Tessa aprendeu a lavar corpos quando ainda precisava subir em um banco para alcançar a mesa de pedra. Anos depois, durante um deslizamento nas muralhas baixas, permaneceu três dias nomeando mortos enquanto soldados cavavam. Desde então, mesmo oficiais apressados esperam que ela termine cada sílaba.\n\nComo sacerdotisa responsável pelos mortos, Tessa ocupa um posto que em Rimewatch é tão estratégico quanto piedoso. Registra sepulturas, autoriza traslados, acompanha patrulhas quando há desaparecidos e mantém a capela pronta para noites em que o sino toca mais de uma vez. Ser Kael a respeita, embora recue quando ela pede recursos para funerais; Mestre Halm lhe envia listas antigas; Orven Geada enfrenta seu olhar quando retorna sem corpos; Lady Ysabet costumava garantir madeira seca para as piras das aldeias do sul.\n\nTessa usa luvas cinzentas mesmo dentro da capela e prende no pescoço um pequeno badalo sem sino. O povo a procura para consolo, mas também para confirmar se um nome foi lembrado. Na crise atual, com relatos de mortos inquietos e Rimewatch em silêncio, sua presença pública é uma promessa severa: ninguém deve atravessar o inverno sem nome, rito e testemunha.",
  "casa-rimerberg:lady-ysabet-rimerberg":
    "Ysabet Rimerberg nasceu no ramo administrativo da Casa, longe do Farol de Gelo e perto dos armazéns onde se decide quem atravessa o inverno com farinha bastante. Sua mãe supervisionava contas de sal-gema; seu pai negociava carroças com Vargen e pequenos mercadores do sul. Quando uma praga atingiu rebanhos nas aldeias baixas, Ysabet ainda era jovem, mas reorganizou rotas de entrega usando capelas, celeiros particulares e torres de sinal como pontos de distribuição. Essa operação lhe rendeu respeito entre camponeses que raramente viam um Rimerberg fora de cerimônia.\n\nComo administradora das aldeias do sul, lidava com impostos, sementes, reparo de pontes, listas de órfãos e reclamações que pareciam pequenas apenas para quem nunca passou fome. Ser Kael dependia de seus números para falar com Asterhall; Orven Geada usava suas listas para planejar patrulhas; Mestre Halm recebia dela observações sobre degelo e migração de animais; Irmã Tessa contava com sua madeira, tecido e registro de nomes. Sua ausência recente deixou lacunas em mesas que já tinham pouco espaço para erro.\n\nYsabet é lembrada pelo casaco azul desbotado, pelos dedos manchados de tinta e pela mania de somar colunas enquanto escuta conversas. Entre aldeões, tem fama de justa porque aparece antes da cobrança e depois dela. Na crise atual, seu nome circula em perguntas cautelosas nas estradas ao sul de Rimewatch, onde cada carroça atrasada pode significar burocracia, neve ou coisa pior.",
  "casa-rimerberg:mestre-halm":
    "Mestre Halm nasceu em uma aldeia de pedra baixa ao sul de Rimewatch, filho de uma parteira e de um reparador de lanternas de sinal. Subiu para a fortaleza como aprendiz depois de um inverno em que previu, pela mudança no vento e pelo silêncio dos corvos, uma avalanche que bloqueou a estrada dois dias depois. Os oficiais riram antes de mandar reforçar os depósitos; quando a neve caiu, pararam de rir. Halm passou a vida registrando clima, sonhos, gelo e mortes com a paciência de quem sabe que o Norte cobra juros sobre descuido.\n\nComo Guardião do Farol de Gelo, não comanda exércitos, mas todos os comandantes já esperaram por sua leitura da chama azul. Conhece os degraus da torre pelo rangido e recita nomes de guardiões que nenhum escriba de Asterhall lembra. Ser Kael o procura antes de enviar mensagens ao sul; Orven Geada discute sinais de patrulha com ele; Irmã Tessa divide vigílias funerárias em noites ruins; Lady Ysabet lhe confiava relatórios das aldeias.\n\nHalm é magro, curvado e mantém a barba presa com fios de cobre para não tocar a chama. O povo o chama de velho sino sem bronze: soa baixo, mas soa certo. Na crise atual, seu nome circula junto ao silêncio do Farol de Gelo, e cada pessoa que olha para o norte pergunta se ele ainda está diante da torre ou se Rimewatch já engoliu mais um guardião.",
  "casa-rimerberg:ser-kael-rimerberg":
    "Kael Rimerberg nasceu em Rimewatch durante um inverno em que as cisternas aquecidas falharam por três noites. Filho de um ramo secundário da Casa, cresceu entre mapas de gelo, listas de ração e sinos de troca de guarda. Quando jovem, acompanhou patrulhas até torres de sinal abandonadas depois do Inverno das Cinzas; numa delas, perdeu dois dedos para o frio e voltou com o diário de um vigia antigo preso sob gelo negro. Desde então, fala como quem mede a distância entre uma ordem e o desastre.\n\nSua ascensão veio pela escassez. Enquanto outros nobres buscavam casamentos ao sul ou cargos menos ingratos, Kael permaneceu nas muralhas, aprendeu a negociar comboios e respondeu às cartas cada vez mais secas de Asterhall. Com o silêncio de Lorde Rimerberg, tornou-se a voz que ainda pode ser ouvida fora da Última Vigília. Mestre Halm o trata como aluno impaciente; Orven Geada obedece, mas discute patrulhas; Irmã Tessa lhe cobra nomes e funerais; a ausência de Lady Ysabet pesa sobre os relatos das aldeias do sul.\n\nO povo o conhece pelo manto remendado com pele clara no ombro esquerdo e pelas frases curtas, quase marteladas. Em Asterhall, sua reputação mistura coragem e aspereza. Na crise atual, Kael sustenta que Rimewatch continua sendo um dever do reino inteiro, mesmo quando sua chama azul já não aparece nas noites do Norte.",
  "casa-valerius:dama-elara-voss":
    "Elara Voss nasceu na Baixa Asterhall, filha de uma família de armeiros que fornecia lanças à Guarda Real antes de possuir brasão próprio. Entrou como escudeira por recomendação de um capitão ferido que a vira conter uma briga de cais sem desembainhar a espada. Anos depois, durante tumultos por pão perto do Mercado das Cinco Estradas, Elara manteve a linha dos guardas aberta para a passagem de curadores da Ordem do Sino, recusando tanto a covardia quanto o massacre. A história circula entre soldados como prova de que sua severidade tem medida.\n\nComo Comandante da Guarda Real, protege o Palácio da Coroa, o Conselho, os arquivos e a regência de Lady Celene. Não pertence aos ramos antigos da Casa, o que lhe dá inimigos discretos entre nobres que preferem genealogia a serviço. Celene confia nela para portas difíceis; Aelric Roderic negocia recursos que ela sempre considera insuficientes; Nerys Thorne registra suas ordens com exatidão desconfortável; Alic passa por seus corredores sob escolta dobrada desde a morte de Edric.\n\nElara é alta, usa o cabelo cortado na nuca e mantém uma cicatriz branca atravessando o queixo. O povo da capital a conhece pela ronda ao amanhecer e pela falta de paciência com guardas bêbados. Depois do ataque a Asterhall, sua Guarda deixou de ser símbolo cerimonial para voltar a ser muralha viva no coração de um reino alarmado.",
  "casa-valerius:lady-celene-valerius":
    "Celene Valerius foi criada na Colina da Coroa, entre genealogias, audiências e a disciplina de uma Casa que transforma precedentes em armas. Filha de um ramo próximo ao trono, aprendeu cedo que um convite pode valer uma fortaleza e que a falta de uma assinatura pode arruinar uma família. O cerco de uma disputa sucessória menor, quando ainda era jovem dama, marcou sua educação pública: Celene viu nobres sorrirem no salão enquanto seus procuradores quebravam alianças nos tribunais. Depois disso, raramente entrou em uma conversa sem conhecer a dívida de quem estava diante dela.\n\nComo esposa de Edric III, ocupou primeiro o espaço que a corte oferecia às consortes: patronagem, cerimônia e reconciliação entre famílias. Com o tempo, passou a organizar votos, favores e concessões com mais precisão que muitos ministros. A morte do rei a colocou sob a tiara da Regência, diante de um herdeiro de doze anos e de Casas que confundem unidade com controle quando Asterhall aperta demais a mão. Aelric Roderic administra contas; Elara Voss guarda portas; Nerys Thorne registra precedentes; Alic comparece às cerimônias sob olhares demais.\n\nCelene é lembrada pelo perfume seco de murta, pelas mangas impecáveis e por citar tratados sem olhar papéis. O povo da capital a chama de firme ou fria, conforme a fila do pão. Depois do ataque a Asterhall e da votação interrompida, governa no centro de uma Coroa que ainda precisa convencer o reino a permanecer inteiro.",
  "casa-valerius:lord-aelric-roderic":
    "Aelric Roderic nasceu em uma família nobre menor ligada aos tribunais de Asterhall, sem terras vastas, mas com várias gerações de serviço em arquivos de receita. Ainda jovem, ganhou fama ao descobrir que três pedágios de estrada eram cobrados com pesos diferentes do padrão real, enriquecendo intermediários e reduzindo grãos destinados aos celeiros centrais. O escândalo derrubou dois magistrados e o colocou no caminho da administração palaciana. Desde então, a corte aprendeu que sua voz calma costuma preceder cortes, cobranças e recibos difíceis de contestar.\n\nComo Mestre de Ofício da Casa Valerius, Aelric cuida de provisões, salários, contratos de reparo, manutenção de estradas e contas que sustentam a Guarda Real antes de qualquer bandeira tremular. Celene o usa como instrumento de precisão, não como ornamento. Elara Voss discute com ele cada vez que uma muralha precisa de mais homens do que a planilha permite; Nerys Thorne fornece precedentes para suas decisões; Alic recebe dele aulas secas sobre o custo de uma ordem. Nobres de salão o chamam de mercador com brasão quando pensam que ele não ouvirá.\n\nAelric tem rosto comprido, cabelo sempre preso com fita escura e o hábito de limpar a pena antes de responder a insultos. Entre servidores e fornecedores, sua reputação é de dureza previsível. Na crise atual, com refugiados chegando, estradas ameaçadas e Asterhall ferida, ele trabalha no ponto onde lealdade vira orçamento e orçamento vira sobrevivência.",
  "casa-valerius:principe-alic-valerius":
    "Alic Valerius nasceu em Asterhall e cresceu sob a vigilância de amas, tutores, guardas e parentes que tratavam cada gesto seu como sinal para o futuro. Filho de Edric III e de Lady Celene, aprendeu leitura de mapas antes de cavalgar sem ajuda, genealogia antes de dançar e silêncio antes de discordar. O evento que o lançou ao centro da ilha não veio de sua infância, mas da morte do rei: de uma semana para outra, o menino pálido que acompanhava cerimônias tornou-se herdeiro diante de Casas que discutem sua idade como se discutissem o peso da própria Coroa.\n\nAlic participa de conselhos, ritos e audiências, mas ainda não usa a Coroa Real. Celene governa como regente e o coloca em lugares onde todos possam lembrar a continuidade Valerius. Aelric Roderic o cerca de lições sobre tributo e abastecimento; Elara Voss vigia seus trajetos pelo palácio; Nerys Thorne lhe mostra cartas antigas com luvas de arquivo; cortesãos medem cada olhar trocado entre mãe e filho.\n\nO príncipe é conhecido pela palidez, pela postura cuidadosa e pelo hábito de observar sinetes antes de rostos. Entre o povo de Asterhall, desperta pena, curiosidade e cálculo, conforme quem fala. Na crise atual, com a coroação antecipada interrompida pelo ataque à capital, Alic permanece como centro frágil de uma disputa que todos dizem tratar da sobrevivência do reino.",
  "casa-valerius:sra-nerys-thorne":
    "Nerys Thorne nasceu entre escribas da Cidade dos Sinos, em uma família que registrava óbitos, doações e disputas de herança para templos e casas funerárias. Foi chamada aos arquivos reais depois de corrigir, diante de um juiz irritado, a data de um decreto que todos citavam errado havia vinte anos. A correção mudou a posse de três pontes menores e ensinou à corte que memória escrita pode valer mais que uma tropa quando chega na hora certa. Nerys nunca esqueceu a sala em que isso aconteceu, nem o nome do juiz.\n\nComo arquivista da Casa Valerius, guarda cartas de reconhecimento, votos do Conselho, genealogias, tratados de fronteira e precedentes usados por Celene para manter as Casas dentro da linguagem da lei. Aelric Roderic depende de seus registros para cobrar sem parecer arbitrário; Elara Voss a procura quando ordens antigas autorizam medidas novas; Alic aprende com ela a diferença entre história celebrada e documento válido. Na corte, alguns a consideram enigmática porque ela raramente corrige duas vezes a mesma pessoa.\n\nNerys usa vestidos escuros sem joia visível e carrega chaves em uma bolsa de couro sob o manto. Seu hábito é soprar a poeira para longe, nunca sobre o texto. Entre servidores, dizem que ela sabe onde cada família esconde sua vergonha pública. Na crise atual, permanece nos arquivos de Asterhall, protegendo papéis que podem decidir votos, heranças e culpas.",
  "casa-vargen:hakon-vargen":
    "Hakon Vargen nasceu poucos anos depois de Elira, no mesmo inverno em que lobos desceram até os currais de Droskar. Cresceu menos nos salões do que nos pátios de treino, disputando força com filhos de caçadores e aprendendo a conduzir cães de neve antes de decorar genealogias. A Estrada Branca o moldou. Numa juventude passada entre comboios, emboscadas e pontes cobertas de gelo, Hakon ganhou cicatrizes nas mãos puxando trenós atolados e abrindo passagem para aldeões que tentavam chegar à fortaleza antes da primeira nevasca grande.\n\nO cargo de Capitão da Estrada Branca veio depois que uma patrulha sob seu comando trouxe de volta quase todos os viajantes de uma caravana perdida entre Stonebridge e Droskar. O feito ainda é contado nas estalagens, com exageros sobre lobos e homens congelados. Dentro da Casa, sua franqueza bate de frente com a prudência de Elira e com as contas de Soren Vale-Branco; Maera o repreende por falar alto demais perto do Muro dos Ausentes. Hakon é lembrado pela barba presa em anéis de ferro simples e por quebrar o gelo de bebedouros com o cabo do machado enquanto conversa. Soldados o seguem porque ele marcha na frente. Na crise do Norte, passa mais tempo fora dos salões do que dentro deles, verificando pontes, marcos e torres apagadas.",
  "casa-vargen:lady-elira-vargen":
    "Lady Elira Vargen nasceu em Droskar, filha de uma linhagem que mede nobreza pelo número de invernos atravessados sem abandonar uma aldeia. Seu pai comandava patrulhas entre Stonebridge e as torres menores da Estrada Branca, e sua mãe administrava banhos aquecidos, canis e depósitos quando os comboios do sul atrasavam. Ainda jovem, Elira viu uma coluna de serradores ficar presa por três noites numa garganta fechada por avalanche. A decisão de abrir os portões da fortaleza e repartir carvão com forasteiros virou uma história repetida nas cozinhas de Droskar, porque ela própria carregou lenha até cair de exaustão.\n\nChegou ao assento de Senhora de Droskar depois de anos mediando chefes de aldeia, capitães e anciãos do Muro dos Ausentes. Hakon, seu irmão, fala mais alto nos salões e empurra a Casa para respostas duras; Elira o escuta, mas raramente deixa que a mesa vire quartel. Maera Lobo-Velho a chama de filha do inverno, enquanto Torvald Neve-Presa resmunga que suas patrulhas recebem freios demais. O povo a conhece pelo manto de pele escura sempre remendado no ombro esquerdo e pelo hábito de servir sopa antes de discutir política. Com Rimewatch silenciosa e Asterhall exigindo votos, Elira permanece em Droskar, pesando cada pedido da Coroa contra os nomes que ainda cabem no muro.",
  "casa-vargen:maera-lobo-velho":
    "Maera Lobo-Velho veio de uma aldeia de carvoeiros acima de Droskar, onde crianças aprendem a ler pegadas antes de ler letras. Jovem, serviu como guia de patrulha e conheceu pelo nome quase todas as famílias espalhadas nos vales próximos. A história que a acompanha começou no Inverno das Três Lanternas, quando uma coluna de batedores não retornou e Maera caminhou dois dias pela mata para recolher placas, botões e pedaços de manto que permitissem gravar nomes corretos no Muro dos Ausentes. Desde então, ninguém em Droskar pronuncia uma lista de mortos sem olhar para ela.\n\nTornou-se Guardiã do Muro por escolha dos anciãos, mas também por insistência dos soldados, que confiavam nela para não transformar perdas em números. Elira a consulta antes de decisões que mexem com aldeias; Hakon baixa a voz quando ela ergue uma sobrancelha; Torvald traz relatórios primeiro a ela quando uma patrulha some tempo demais. Maera anda com uma bengala de raiz retorcida, usa tranças brancas presas por ossos de lebre e passa cinza nas letras recém-abertas da pedra. O povo a chama para nomear crianças e despedir viajantes. Com Rimewatch em silêncio, ela permanece junto ao muro, preparando espaço novo sem declarar em voz alta para quem será.",
  "casa-vargen:soren-vale-branco":
    "Soren Vale-Branco nasceu em Droskar, filho de uma escrivã de armazém e de um moleiro que conhecia o preço de cada saco de centeio quando a Estrada Branca fechava. Nunca teve a fama marcial de Hakon nem o prestígio ritual de Maera, mas cresceu ouvindo mães discutirem medidas de farinha e capitães pedirem carne seca para patrulhas que talvez não voltassem. O episódio que o colocou diante da Casa foi a quebra de três pontes no mesmo inverno. Enquanto homens armados gritavam por prioridade, Soren reorganizou depósitos, banhos, carvão e rações por marcas de aldeia, evitando que os povoados menores desaparecessem das contas.\n\nA administração de provisões lhe deu autoridade sem carinho. Elira o usa como contrapeso nas reuniões, Hakon o acusa de deixar números entre soldados e sopa, e Torvald vive arrancando dele suprimentos para rotas duvidosas. Soren usa mangas sempre dobradas, dedos manchados de tinta e um cordão com fichas de osso que representam armazéns. Nas filas de Droskar, muita gente range os dentes ao ouvir seu nome, mas poucos negam que os depósitos ficam mais honestos sob sua chave. Com refugiados chegando por Stonebridge e a capital prometendo auxílio incerto, ele passa noites comparando inventários à luz ruim, cercado por mapas de neve e barris lacrados.",
  "casa-vargen:torvald-neve-presa":
    "Torvald Neve-Presa nasceu numa família de caçadores que vivia entre Droskar e as torres de sinal do norte habitado. Aprendeu a desaparecer em pinheirais antes de saber manejar espada, e por anos foi conhecido apenas como o rapaz que voltava com mapas riscados em couro cru e notícias de trilhas que ninguém mais usava. Seu nome de guerra veio de uma patrulha durante degelo traiçoeiro: preso sob neve quebrada até a cintura, ele matou um lobo com a faca curta e guiou os companheiros de volta por marcas de musgo nas pedras.\n\nComo Mestre dos Batedores, responde pelos olhos mais distantes da Casa Vargen. Seus homens o respeitam porque ele divide frio, fome e risco, mas chefes de aldeia reclamam que suas rotas às vezes passam perto demais de lugares que deveriam ficar quietos. Elira o mantém perto pela utilidade e pela dificuldade de substituí-lo; Hakon gosta de sua ousadia; Soren detesta a maneira como ele gasta botas, flechas e carne seca. Torvald tem um dente de lobo preso ao gorro e o hábito de cheirar neve antes de ordenar marcha. Entre o povo, é meio herói, meio mau presságio, pois sua chegada costuma anteceder notícias ruins. Agora, com torres mudas rumo a Rimewatch, seus batedores levam mensagens, contam pegadas e somem por dias entre árvores pesadas de gelo.",
  "cla-mandibula-de-osso:brakka-quebra-ferro":
    "Brakka Quebra-Ferro nasceu perto das oficinas de Gor-Kirius, onde correntes antigas são guardadas não como troféu, mas como material a ser desfeito. Sua avó atravessou o Rio Bravio com os pulsos marcados; seu pai aprendeu ferraria consertando ferramentas quebradas por gente que não podia esperar caravanas. Brakka cresceu entre fole, carvão e histórias de peças élficas arrancadas de ruínas em Na'usca. O evento que fixou seu nome ocorreu na Memória de Kirius, quando ela aqueceu uma corrente cerimonial até o branco e a transformou, diante da praça, em pontas de lança entregues a jovens patrulheiros.\n\nComo ferreira do clã, abastece Ursa Dente-Verde, corrige armas de Garok sem baixar os olhos e lembra a Thorgul quando promessas de metal estrangeiro chegam atrasadas. Morgruk abençoa algumas de suas peças, mas Brakka costuma dizer que uma lâmina mal temperada não melhora com canto bonito. Ela tem ombros queimados por faíscas, um avental grosso remendado com couro de javali e o hábito de morder pregos enquanto escuta pedidos. O povo a procura para ferramentas de caça tanto quanto para armas. Em tempos de mensagens truncadas e ameaças no Norte, sua oficina trabalha depois do pôr do sol, martelando ferro velho até que a cidade inteira saiba que Gor-Kirius não esqueceu como se arma.",
  "cla-mandibula-de-osso:garok-do-trovao":
    "Garok do Trovão cresceu em Gor-Kirius como filho de Thorgul Crânio Cinzento, mas sua infância foi menos confortável do que estrangeiros imaginam para um herdeiro. Entre os Mandíbula de Osso, o filho de chefe aprende primeiro a carregar água, afiar lâmina dos outros e ouvir os velhos repetirem a fuga de Kirius até saber onde cada remo quebrou no Rio Bravio. Garok recebeu seu nome depois de uma tempestade nas Grandes Chuvas, quando correu para puxar crianças de uma ponte de madeira prestes a ceder. A história correu pelas aldeias antes que os anciãos a aparassem de exagero.\n\nHoje é tratado como futuro líder provável, acompanhado de perto por guerreiros jovens e observado com severidade por Morgruk, Ursa Dente-Verde e Brakka Quebra-Ferro. Thorgul o deixa falar nas assembleias, mas o silêncio do pai costuma ensinar mais que repreensão. Garok tem voz alta, riso fácil e duas marcas de raio tatuadas nos braços, feitas por um velho cantador que jurou ter ouvido Niantã naquela chuva. O povo o recebe bem nos pátios de treino e com cautela nos conselhos. Na crise de Valdren, aparece nas bordas de Gor-Kirius, entre patrulhas e reuniões, como sinal de uma geração que nasceu livre e já discute o preço de continuar assim.",
  "cla-mandibula-de-osso:morgruk":
    "Morgruk nasceu numa aldeia de Na'usca onde as raízes entram pelas paredes das casas e todo juramento é ouvido diante de folhas vivas. Sua família guarda cantos de Niantã desde os primeiros anos após a fuga de Kirius, quando os libertos ainda não sabiam quais frutos alimentavam e quais matavam. Na juventude, Morgruk guiou caçadores por uma cheia do Rio Bravio que engoliu trilhas e altares. Ao retornar com os sobreviventes, trouxe também sementes de uma árvore rara, plantadas depois junto ao túmulo de Kirius. Esse gesto o fez conhecido como alguém capaz de tratar sobrevivência e rito como partes da mesma respiração.\n\nComo cacique e guardião de Niantã, preside cerimônias, escuta disputas familiares e fala quando a floresta entra na política do clã. Thorgul respeita sua palavra antiga; Garok se impacienta com seus longos silêncios; Ursa aceita suas bênçãos, embora reclame quando ele atrasa patrulhas para ler sinais de chuva e pássaros. Morgruk usa um manto de fibras verdes, presas pequenas furadas por contas de madeira e carrega um cajado vivo que brota folhas novas após as Grandes Chuvas. O povo o chama para curas, nascimentos e desacordos que não cabem em lâmina. Com a ilha em crise, ele permanece em Gor-Kirius lembrando que a cidade dos livres também depende de uma mata que não responde a decretos.",
  "cla-mandibula-de-osso:thorgul-cranio-cinzento":
    "Thorgul Crânio Cinzento nasceu entre os salões de madeira de Gor-Kirius, quando a cidade ainda cheirava a barro novo e fumaça de paliçada. É neto de gente que desceu o Rio Bravio na fuga de Kirius, e sua família conserva uma tigela rachada, usada para dar água a fugitivos que chegaram sem nome registrado em livro algum. A juventude de Thorgul foi marcada pela primeira grande disputa por madeira nas bordas de Na'usca, quando aldeias vizinhas acusaram os orcs de avançar sobre trilhas antigas. Ele ganhou fama não por vencer uma escaramuça, mas por obrigar guerreiros exaltados a ouvir Morgruk antes que sangue demais fosse derramado.\n\nA liderança do clã veio pelo respeito acumulado em assembleias, caçadas e julgamentos, não por ornamento. Garok do Trovão caminha à sua sombra com voz de tempestade; Ursa Dente-Verde garante que nenhuma fronteira fique sem olhos; Brakka Quebra-Ferro entrega armas feitas de correntes antigas e não adoça palavra para chefe nenhum. Thorgul é reconhecido pelo crânio grisalho raspado nas laterais, pelas presas gastas e pelo costume de tocar o chão antes de falar de Kirius. Entre o povo, chamam-no de velho tronco: duro, cheio de marcas, bom para amarrar a casa durante enchente. Na crise atual, responde de Gor-Kirius a convites da Coroa com a memória do Tempo sem Nomes sobre a mesa.",
  "cla-mandibula-de-osso:ursa-dente-verde":
    "Ursa Dente-Verde nasceu nas bordas de Na'usca, numa comunidade que via primeiro os invasores, os caçadores perdidos e os cobradores de madeira vindos de fora. Sua mãe comandava armadilhas de trilha; seu pai conhecia ervas que fechavam feridas sem deixar soldado dormir. A fama de Ursa começou quando um grupo de saqueadores tentou levar crianças durante a estação das chuvas. Ela não era a mais velha da patrulha, mas foi sua emboscada que separou os invasores, salvou os reféns e deixou marcas talhadas em três árvores como aviso. Desde então, viajantes reduzem o passo quando veem dentes pintados de verde em postes de fronteira.\n\nChefe das patrulhas, Ursa responde a Thorgul, discute com Garok quando entusiasmo vira barulho e consulta Morgruk antes de cruzar áreas sagradas, ainda que o faça com evidente impaciência. Brakka fornece suas lâminas curtas, pesadas na ponta, feitas para mato fechado. Ursa raspa uma lateral da cabeça, usa colares de presas tingidas e não se senta de costas para porta alguma. Entre aldeões, sua reputação mistura alívio e desconforto: todos dormem melhor quando ela vigia, poucos relaxam em sua presença. Na crise atual, reforça trilhas, interroga forasteiros e trata cada mensagem da Coroa como algo que deve ser escoltado até provar que não morde.",
  "coroa:alic-valerius":
    "Alic Valerius nasceu em Asterhall durante um eclipse total, fato que a cidade transformou em presságio antes que as parteiras terminassem de lavar as mãos. Filho do rei Edric III e de Lady Celene, cresceu entre tutores de direito, cerimônias, retratos de Alaric, arquivos de linhagem e guardas treinados para fingir que não observavam uma criança. A morte do pai colocou sobre ele uma atenção que poucos adultos suportariam com graça. Publicamente, o príncipe respondeu com silêncio, postura correta e uma memória incômoda para detalhes.\n\nNa corte, Alic é visto como menino educado demais para sua idade e difícil de ler. Senta-se perto da regente, escuta conselheiros, lembra pequenas contradições e raramente desperdiça pergunta. Escribas comentam que ele prefere a Galeria das Linhagens aos jardins. Lady Celene o apresenta como continuidade da Casa Valerius; alguns embaixadores saem das audiências elogiando sua compostura, outros reclamam de terem sido examinados como documentos.\n\nÉ magro, pálido, sempre vestido com azul escuro sem joia chamativa. Na Baixa Asterhall, mães o citam como pobre órfão real; nas embaixadas, seu nome pesa como futuro decreto. Na crise atual, sua coroação antecipada divide as Casas enquanto a cidade, atacada e cheia de rumores do Norte, espera saber que tipo de rei caberia numa criança.",
  "grande-casa-ulgar:asha-tres-cicatrizes":
    "Asha Três-Cicatrizes pertence ao clã Casco Longo, conhecido entre os Ulgar por rastrear rebanhos, achar água e voltar quando mapas já não servem. As três cicatrizes que lhe dão nome cruzam o rosto e o peito: uma de predador de Nah'Korah, uma de Valgor durante a fuga e uma aberta em Arven por javali maior do que qualquer animal que ela conhecia. Nos primeiros meses em Valdren, quando Rok'thar ainda era paliçada e lama, Asha organizou grupos de caça que impediram a fome de alcançar as tendas centrais. A partir dali, sua palavra passou a pesar tanto quanto a de muitos chefes.\n\nResponsável pela caça e provisões, negocia com Thorgar quando guerreiros pedem carne para marchas, enfrenta Varka quando patrulhas espantam caça, e trabalha com Rokan para abrir secadouros e currais. Mok'Thar abençoa suas partidas; Nima tenta aprender com ela os nomes das plantas de Arven, recebendo respostas secas e úteis. Asha usa colares de dentes pequenos, carrega duas lanças leves e marca árvores com cortes quase invisíveis. O povo de Rok'thar a conhece pela capacidade de distribuir sem discurso. Forasteiros a veem nos limites da floresta, contando pegadas antes de aceitar conversa. Na crise atual, sua rotina pesa sobre cada panela, porque política alguma convence estômagos vazios.",
  "grande-casa-ulgar:mok-thar":
    "Mok'Thar era xamã antes de Valdren aprender o nome dos Ulgar. Em Nah'Korah, pertenceu à linhagem Olhos de Cinza, guardiã de cinzas rituais, relatos de migração e pactos feitos com espíritos de montanha. Quando a Vor'Kaash consumiu rios e pastos, coube a ele preservar cânticos enquanto guerreiros seguravam Valgor longe do círculo do portal. Os sobreviventes dizem que Mok'Thar atravessou por último entre os xamãs de sua tenda, trazendo numa cuia cinza da última fogueira ancestral. Em Rok'thar, essa cinza foi misturada à Chama do Primeiro Refúgio.\n\nComo Grande Xamã, senta-se ao lado de Thorgar Crina de Ferro nos ritos públicos, mas não ocupa o mesmo tipo de poder. Varka Chifre Rubro o respeita em cerimônia e desafia seus avisos quando há aço sobre a mesa; Nima Olhos de Cinza o segue como aprendiz inquieta; Rokan Pedra Oca pede sua presença antes de fincar estacas centrais. Mok'Thar tem chifres longos, cobertos por tecido queimado, e fala com pausas que fazem até crianças diminuírem o passo. Forasteiros o tratam como presságio ambulante; Ulgar o tratam como arquivo vivo. Na crise atual, seus ritos acompanham caçadores, diplomatas e funerais incompletos, enquanto Rok'thar tenta aprender quais espíritos de Arven aceitam ouvir nomes vindos de outro mundo.",
  "grande-casa-ulgar:nima-olhos-de-cinza":
    "Nima Olhos de Cinza nasceu pouco antes da fuga de Nah'Korah, mas suas lembranças do mundo perdido são fragmentos de calor, mugidos distantes e adultos falando baixo demais. Em Valdren, cresceu já dentro de Rok'thar, entre tendas que viravam casas e cerimônias inventadas porque os ritos antigos precisavam de uma terra que ficou para trás. Sua família pertence à mesma tradição de Mok'Thar, embora Nima tenha aprendido cedo que carregar um nome venerável não faz os espíritos responderem mais depressa. O primeiro episódio comentado sobre ela ocorreu quando ouviu, durante uma vigília, o canto de pássaros de Arven e o repetiu no ritmo de uma ladainha Ulgar, acalmando crianças assustadas por uma noite inteira.\n\nComo jovem xamã, acompanha Mok'Thar, observa Asha nas matas e faz perguntas que deixam guerreiros desconfortáveis. Varka a chama de bezerra cinzenta quando perde a paciência; Thorgar a trata com formalidade pública; Rokan pede que ela escute o vento dentro de torres novas. Nima tem olhos claros como cinza lavada, chifres ainda curtos e os dedos manchados por carvão ritual. Entre os Ulgar mais velhos, desperta ternura e desconfiança na mesma medida. Com Valdren mergulhada em frio, mensagens e mortos inquietos, ela passa cada vez mais tempo nas bordas de Arven, tentando aprender a língua espiritual de uma floresta que não nasceu com seu povo.",
  "grande-casa-ulgar:rokan-pedra-oca":
    "Rokan Pedra Oca veio de um clã de construtores que, em Nah'Korah, abria abrigos no interior de colinas e erguia cercas para rebanhos durante tempestades de poeira. A destruição do mundo natal transformou seu ofício em urgência. Quando os Ulgar chegaram a Arven, ele foi um dos primeiros a notar que a madeira local rachava de outro modo, que o solo encharcava fossos depressa e que paliçadas copiadas de Nah'Korah cairiam na primeira estação de chuva forte. O episódio que firmou sua autoridade foi a reconstrução de uma torre desabada sem interromper a guarda, usando troncos ocos, barro e pedra trazida em trenós improvisados.\n\nComo construtor de Rok'thar, responde por casas, fossos, currais, passarelas e pela difícil tarefa de transformar acampamento de refugiados em cidade. Thorgar o escuta quando mapas entram na conversa; Varka o acusa de pensar em parede quando deveria pensar em lança; Asha cobra depósitos secos; Mok'Thar exige que certas estacas respeitem ritos de fundação. Rokan tem um chifre quebrado na ponta, mãos sempre cheias de resina e o hábito de bater nas vigas com a testa para testar som e firmeza. Crianças o seguem porque ele deixa lascas boas para brinquedos. Em meio à crise, trabalha em Rok'thar com pressa contida, abrindo espaço para famílias e para cercos que talvez nunca recebam aviso.",
  "grande-casa-ulgar:thorgar-crina-de-ferro":
    "Thorgar Crina de Ferro atravessou para Valdren à frente de clãs que ainda traziam poeira de Nah'Korah presa na pelagem. Antes do portal, era chefe de caravana armada, criado entre rebanhos, pedras de juramento e disputas de pastagem. A queda da Terra-Mãe transformou o ofício de conduzir em algo maior: contar sobreviventes, separar feridos dos mortos e manter unidas linhagens que haviam perdido aldeias inteiras. Em Arven, durante os primeiros dias de Rok'thar, foi visto dormindo de pé junto à Chama do Primeiro Refúgio, com um machado na mão e crianças abrigadas atrás de seu escudo.\n\nO título de Grão-Chefe veio quando Crina de Ferro, Chifre Rubro, Pedra Oca, Olhos de Cinza e outros clãs aceitaram falar por uma só voz diante de Valdren. Mok'Thar carrega a memória espiritual que Thorgar consulta em público; Varka Chifre Rubro o desafia nos conselhos de guerra; Rokan Pedra Oca transforma suas ordens em paliçadas, fossos e casas. Ele tem chifres ferrados com anéis escuros, cada um gravado com nomes de clãs perdidos, e costuma ouvir sem se sentar quando negocia com enviados humanos. Muitos aldeões de Arven ainda o chamam de invasor; entre os Ulgar, seu nome é dito junto ao fogo. Agora, com a Coroa discutindo pertencimento e guerra, Thorgar permanece em Rok'thar como rosto pesado de um povo recém-chegado.",
  "grande-casa-ulgar:varka-chifre-rubro":
    "Varka Chifre Rubro nasceu no clã de guerreiros que mais tarde daria seu nome à ala marcial da Grande Casa Ulgar. Em Nah'Korah, aprendeu a lutar protegendo rebanhos contra predadores e, depois, linhas de fuga contra os Valgor. A travessia para Valdren não apagou sua fama. Durante os primeiros confrontos em Arven, quando aldeões e soldados da Coroa ainda viam os Ulgar como ameaça indistinta, Varka comandou uma retirada em meia-lua que salvou feridos e abriu caminho até a clareira onde Rok'thar seria erguida. A manobra é repetida nos treinos, geralmente com mais gritos do que elegância.\n\nO título de Senhora da Guerra veio por reconhecimento dos clãs armados, não por agrado a Thorgar. Ela e o Grão-Chefe se chocam diante de enviados e anciãos; Mok'Thar tenta moderar os conselhos; Asha Três-Cicatrizes cobra dela caçadores vivos, não apenas vitórias; Rokan reclama quando suas paliçadas viram alvo de demonstração. Varka possui pelagem escura, chifres pintados com argila vermelha e uma risada curta que costuma preceder ordens difíceis. Entre os Ulgar jovens, é figura de orgulho. Entre vizinhos de Arven, seu nome fecha portas. Com a Coroa debatendo reconhecimento e guerra, ela treina lanças no barro de Rok'thar e comparece a reuniões armada até os dentes.",
  "irmandade-dos-corvos:alva-pena-branca":
    "Alva Pena-Branca cresceu perto dos pátios de hospedaria de Raven's Cross, onde viajantes sem destino fixo deixam nomes falsos e crianças aprendem cedo a observar botas. Entrou na Irmandade como registradora de chegadas, função modesta que exigia memória para rostos e paciência para histórias mal contadas. Sua carreira mudou quando uma jovem aprendiz de mensageiro desapareceu entre dois postos e Alva reconstituiu o caminho por recibos de cevada, uma mancha de cera azul e o depoimento de uma cozinheira ignorada pelos guardas. A aprendiz foi encontrada viva. Desde então, desaparecidos passaram a chegar à sua mesa antes de virarem lenda de estrada.\n\nResponsável por Desaparecidos, Alva trabalha na fronteira entre arquivo e dor. Corva Nera cobra discrição; Sino Mudo transforma seus casos em padrões; Tomas Três-Pontes cede carruagens quando pode; Bico de Ferro Ren oferece homens, mas nem sempre paciência para perguntas longas. Alva usa uma pena clara atrás da orelha, não como ornamento, e sim para lembrar qual lado da página ainda está em branco. Fala pouco com nobres e muito com criados, barqueiros, cocheiros e crianças. O povo a procura quando a Justiça Real parece longe demais. Com Rimewatch muda e refugiados chegando sem listas completas, sua sala em Raven's Cross enche de nomes, descrições de casacos e objetos guardados para donos que talvez ainda estejam na estrada.",
  "irmandade-dos-corvos:bico-de-ferro-ren":
    "Bico de Ferro Ren veio de uma linhagem de guardas de posto, gente que mede honra pela quantidade de mensageiros que atravessou noite ruim sob sua proteção. Antes de receber nome de Corvo, serviu como escudeiro de escolta na Estrada da Estrela e aprendeu a lidar com ladrões, nobres bêbados, desertores e viajantes que confundiam imunidade da Irmandade com fraqueza. O feito que lhe deu reputação ocorreu quando manteve um posto cercado por salteadores até a chegada de reforços, usando portas travadas, azeite fervido e uma corneta rachada que soou a cada hora para fingir mais homens do que havia.\n\nComo Comandante dos Guardas, Ren comanda Bicos de Ferro, escoltas de carruagem e proteção de torres de aves. Corva Nera aprecia sua disciplina e corta seus excessos; Tomas reclama que ele pesa as rotas com homens armados; Alva exige que seus guardas procurem pessoas, não apenas culpados; Sino Mudo lhe entrega sinais de ameaça em silêncio irritante. Ren mantém a barba curta, usa peitoral escurecido sem brilho e afia a mesma faca toda manhã, mesmo quando não precisa. Mercadores o consideram duro, mensageiros o consideram necessário. Na crise atual, com estradas interrompidas e boatos correndo mais rápido que cavalos, ele reforça portões de Raven's Cross e trata cada atraso como possível ataque.",
  "irmandade-dos-corvos:corva-nera-quatro-estradas":
    "Corva Nera Quatro-Estradas entrou na Irmandade ainda menina, deixada em Raven's Cross por uma família de cocheiros que havia perdido tudo numa disputa de pedágio. Abandonou o sobrenome como manda a regra dos Corvos e aprendeu primeiro a limpar gaiolas, selar bolsas de couro e distinguir o passo de uma carruagem vazia do de uma carregada com prata. O episódio que fixou seu nome ocorreu numa noite de neblina, quando quatro mensagens contraditórias chegaram de direções diferentes e ela reconstruiu a rota verdadeira por manchas de lama, penas cortadas e um erro de cifra. Desde então, a Casa das Mil Janelas passou a tratá-la como alguém que enxergava estradas mesmo de olhos fechados.\n\nA ascensão a Mestra veio por arquivo, disciplina e dívida cobrada na hora exata. Sino Mudo lidera as Penas Cinzentas com método próprio e nem sempre aprova sua mão pesada; Tomas Três-Pontes mantém carruagens rodando apesar de ordens que mudam ao amanhecer; Alva Pena-Branca e Bico de Ferro Ren cobram dela mais apoio para desaparecidos e escoltas. Corva usa luvas pretas sem enfeite e carrega um tinteiro de osso preso ao cinto, hábito que faz mensageiro nenhum falar descuidado perto dela. O povo de Raven's Cross a respeita mais do que ama. Com Rimewatch muda e rumores chegando antes de cartas, ela segura a reputação da Irmandade como quem segura uma ave ferida pelo pescoço.",
  "irmandade-dos-corvos:sino-mudo":
    "Sino Mudo chegou à Irmandade dos Corvos sem voz durante a febre que matou metade de sua rua em Raven's Cross. Era filho de uma lavadeira de estalagem e de um copista de mapas menores, desses que registram atalhos, pontes ruins e poços confiáveis. Aprendeu a se comunicar por batidas na mesa, sinais de pena e expressões tão precisas que mentirosos se denunciavam tentando interpretá-lo rápido demais. O episódio que o tornou conhecido veio quando descobriu um desvio de mensagens reais comparando horários de sinos, troca de cavalos e o peso de lama seca em rodas de carruagem. Desde então, as Penas Cinzentas o tratam como faca guardada em estojo simples.\n\nComo chefe desse círculo de analistas, Sino Mudo organiza rumores, cifras quebradas e relatos de desaparecimento que ainda não viraram notícia pública. Corva Nera valoriza sua precisão, embora os dois discordem sobre quanto peso uma instituição consegue carregar sem apodrecer; Tomas Três-Pontes fornece horários; Alva Pena-Branca leva casos humanos demais para caberem em tabela; Ren exige nomes de ameaças antes que existam provas. Sino usa um sino pequeno sem badalo preso ao pescoço e escreve com pena cortada curta. O povo quase não o vê, mas muitos sentem sua mão quando uma mentira perde caminho. Com as rotas do Norte falhando, ele passa noites nos Arquivos de Pena, ligando silêncios que talvez já sejam mensagens.",
  "irmandade-dos-corvos:tomas-tres-pontes":
    "Tomas Três-Pontes nasceu numa família de cocheiros que servia a Raven's Cross havia três gerações. Recebeu o nome de estrada depois de atravessar, no mesmo dia, três pontes quase destruídas para entregar remédios à Abadia Branca e trazer de volta cartas de quarentena. Antes de entrar formalmente na Irmandade, conhecia cocheiras, ferradores, atalhos de inverno e a personalidade de cada cavalo melhor do que conhecia brasões. Sua formação aconteceu nas rodas e nos arreios: aprendeu que uma mensagem não chega por ter selo bonito, mas porque alguém alimentou o animal certo na hora certa.\n\nComo Mestre das Carruagens, responde pelo corpo mais visível da rede dos Corvos. Corva Nera o pressiona por horários impossíveis; Sino Mudo lhe pede registros sem borrões; Alva Pena-Branca desvia seus veículos para buscas; Bico de Ferro Ren exige escoltas extras que atrasam tudo. Tomas sorri mais que a maioria da Irmandade, usa casaco encerado cheirando a palha molhada e guarda pregos de ferradura nos bolsos para dar sorte a aprendizes. Estalajadeiros gostam dele, porque paga consertos antes de discutir culpa. Em tempos normais, sua reputação é a de homem que faz estrada ruim parecer administrável. Na crise atual, com neve, ataques e cartas contraditórias, ele mantém pátios cheios de rodas quebradas e ainda encontra jeito de mandar uma carruagem sair ao amanhecer.",
  "ordem-do-sino:edras-fulgrim":
    "Edras Fulgrim nasceu numa família de sineiros menores da Cidade dos Sinos, em Asterhall, onde o som dos bronzes marcava partos, sentenças e enterros. Ainda jovem foi enviado à Abadia Branca depois de memorizar, sem erro, os nomes de quarenta e três mortos de uma cheia do Valen. Formaram-no os Irmãos do Bronze e as Irmãs da Memória, mas sua reputação nasceu nos cemitérios em terraços, quando conduziu uma Vigília dos Nomes durante três noites de Bruma baixa sem permitir que uma única sepultura fosse aberta sem testemunha. Desde então, sua voz passou a ser associada ao rito correto e à autoridade severa da Ordem do Sino.\n\nComo Primeiro Tocador, Edras guarda o Sino de Edras e fala com a Coroa em tom de obediência limitada: reconhece leis, mas não entrega a morte aos decretos de Asterhall. Ysara Bel o consulta e também o contém; Maelis o acusa de às vezes preferir o arquivo ao leito; Talia respeita sua firmeza. O povo comum o vê como homem justo e frio. Usa luvas brancas mesmo no calor e nunca começa uma audiência antes de tocar com o polegar uma pequena campainha de prata. Com refugiados vindos do Norte, permanece na Abadia Branca, presidindo funerais, quarentenas e a difícil pergunta sobre quando o Grande Sino deve falar pelo reino.",
  "ordem-do-sino:irma-talia-veu-branco":
    "Talia Véu-Branco nasceu perto de Droskar, numa família de guardas de torre que acendia fogueiras de sinal e enterrava patrulheiros quando a neve permitia. A Ordem do Sino a acolheu após um inverno em que ela guiou três crianças por um cemitério coberto de Bruma, tocando uma faca contra uma caneca para mantê-las seguindo o som. Na Abadia Branca, não se adaptou aos bancos de escola, mas aprendeu ritos de contenção, armas curtas e a leitura de solo revirado nos campos santos. Sua mestra foi Madre Isolde Venn, da Ordem dos Três, em investigações de funerais incompletos. Talia ficou conhecida quando seus Vigias dos Túmulos impediram que saqueadores abrissem covas de soldados sem pagamento às famílias.\n\nComandante dos Vigias, ela patrulha cemitérios, ossários, rotas de traslado e lugares onde a despedida falhou. Edras valoriza sua coragem, mas tenta mantê-la sob rito; Ysara negocia suas queixas; Padre Jeren a chama para proteger peregrinos pobres; Othran fornece mapas de sepultura que ela devolve sujos de lama. Camponeses a veem como a irmã que chega tarde da noite com lanterna e espada curta, sem pedir licença ao medo alheio. Usa um véu branco preso por grampo de ferro e nunca tira as botas dentro da Abadia. Com os mortos do Norte inquietando o reino, Talia reúne Vigias para escoltar corpos, fechar valas e decidir quais cemitérios já não podem ficar sem guarda.",
  "ordem-do-sino:irmao-daron-bronze-puro":
    "Daron nasceu nas oficinas da própria Abadia Branca, filho de fundidores que serviam à Ordem do Sino havia três gerações. Aprendeu primeiro a escutar metal: o estalo do molde ruim, a nota falsa do bronze apressado, o suspiro da fornalha quando a liga aceita prata. A fé lhe veio pelo ofício, pois cada sino que saía das fundições era consagrado com nomes de vivos que o ofereceram e mortos que ele deveria acompanhar. Seu mestre, Irmão Calvo Rûen, obrigava aprendizes a assistir funerais antes de permitir que tocassem o metal. Daron ganhou fama ao refundir um sino rachado de Stonebridge sem apagar a inscrição das famílias que o haviam doado, trabalho que os artesãos de Khazdrun ainda citam com respeito.\n\nComo mestre das fundições, Daron governa calor, carvão, aprendizes e temperamentos. Edras exige dele pureza ritual; Maelis pede sinetas leves para enfermarias; Othran fiscaliza cada dedicatória; jovens irmãos discutem com ele sobre novas formas e ligas. O povo o conhece pelo avental escurecido e pela barba presa em anéis de bronze, além do hábito de bater duas vezes em qualquer mesa antes de sentar. Na crise atual, sua oficina trabalha sem descanso: sinos de campo para funerais no Norte, placas de nome para refugiados e pequenos bronzes que famílias penduram nas janelas quando a Bruma desce.",
  "ordem-do-sino:mae-maelis-da-mao-serena":
    "Maelis nasceu numa aldeia de estrada entre Stonebridge e a Abadia Branca, onde viajantes deixavam mais doenças que moedas. Sua mãe preparava compressas para tropeiros, e o pai cavava covas quando o inverno fechava o caminho. A fé entrou em sua vida pelo hospital, não pelo púlpito: uma irmã do Bronze a levou como ajudante depois de vê-la manter uma criança febril acordada durante uma noite inteira, cantando os nomes dos avós da menina para que ela não se sentisse sozinha. Na Abadia, Maelis aprendeu anatomia simples, orações de passagem e o costume de lavar as mãos antes de tocar vivos e mortos. Seu nome correu Valdren após a Praga das Velas Úmidas, quando abriu enfermarias em antigas hospedarias de peregrinos.\n\nChefe dos hospitais, Mãe Maelis é um dos rostos mais amados da Ordem do Sino. Edras a respeita, embora suas prioridades se choquem; Ysara a ouve quando faltam leitos; Padre Jeren compartilha sua misericórdia; Daron mantém para ela bacias, sinetas e instrumentos de bronze. O povo diz que sua mão pousa leve até em ferida de guerra. Ela é larga de ombros, usa mangas arregaçadas sob o hábito e guarda ervas secas em saquinhos costurados por pacientes. Agora recebe feridos e refugiados do Norte, separando febre, luto e suspeita de morte inquieta nos corredores lotados da Abadia Branca.",
  "ordem-do-sino:othran-sete-tintas":
    "Othran Sete-Tintas veio de Porto Cinzento, neto de um registrador de cargas e de uma lavadeira que bordava nomes em mortalhas para marinheiros sem família. Entrou na Ordem do Sino como copista, depois de provar que conseguia distinguir sete tintas negras usadas em arquivos funerários adulterados. Sua fé nasceu do papel: para ele, o último toque começa quando alguém escreve corretamente quem viveu. Foi formado pelas Irmãs da Memória e por velhos arquivistas que ensinavam a cheirar mofo, rasura e mentira. O episódio que o tornou conhecido ocorreu após um incêndio nos depósitos baixos da Abadia, quando reconstruiu uma lista de mortos a partir de contas de farinha, fitas de caixão e metade de um livro chamuscado.\n\nGuardião do Arquivo dos Nomes, Othran vive entre estantes subterrâneas, genealogias, certidões e sinos pequenos usados para chamar escribas. Ysara depende de sua precisão; Edras admira seu zelo; Maelis reclama que ele exige formulários até na porta da enfermaria; Talia o procura quando túmulos são violados. Para o povo, é um santo estranho ou um burocrata impossível, conforme a fila. Tem manchas permanentes nos dedos, cada uma de cor diferente, e fala com pergaminhos como se fossem idosos frágeis. Na crise atual, compara registros de Rimewatch, Stonebridge e aldeias abandonadas, tentando dar nome aos que chegam sem voz.",
  "ordem-do-sino:padre-jeren-eco-manso":
    "Jeren Eco-Manso veio dos Campos Dourados, de uma família de pequenos arrendatários acostumada a funerais simples, feitos entre colheita e dívida. Ainda jovem cantava para idosos enquanto os parentes trabalhavam nos canais; uma Irmã da Memória o levou à Abadia Branca depois de ouvi-lo recitar nomes de mortos que nem a família rica da aldeia lembrava. Sua formação passou pelos hospitais de Maelis, pelas capelas de estrada e pelos debates litúrgicos que dividem Guardiões, Purificadores e Silenciosos. O feito que o tornou amado ocorreu numa fome local, quando convenceu três comunidades rivais a compartilhar uma única Vigília dos Nomes, poupando famílias pobres de taxas e humilhações públicas.\n\nPadre Jeren defende ritos compassivos, com espaço para culpa, pobreza e despedidas imperfeitas. Edras o considera necessário, embora frouxo demais em certos detalhes; Maelis o chama para leitos difíceis; Talia o protege quando ortodoxos ameaçam seus cortejos; Daron fundiu para ele um sino de som baixo, usado em enfermarias. Entre peregrinos, Jeren é tratado como sacerdote que escuta antes de corrigir. É magro, anda com sandálias gastas mesmo no frio e costuma recolher fitas de nome caídas no chão. Na crise atual, acompanha refugiados em Abadia Branca, improvisando funerais para corpos sem família e defendendo que o medo dos mortos não apague a ternura devida aos vivos.",
  "ordem-do-sino:primeira-tocadora-ysara-bel":
    "Ysara Bel nasceu em Aurivale, filha de uma copista de celeiros e de um cantor litúrgico que conduzia funerais rurais nos meses de fome. A família a enviou à Abadia Branca depois que ela corrigiu, ainda menina, a ordem de leitura dos Sete Toques durante a despedida de um arrendatário sem parentes. Sua formação passou pelas escolas de escribas, pelos hospitais e pelo Arquivo dos Nomes, onde aprendeu que uma genealogia pode alimentar uma viúva ou negar pão a uma criança. Ganhou prestígio ao mediar uma disputa entre famílias de Asterhall e monges da Abadia sobre corpos trazidos de uma ponte caída, garantindo sepultura sem apagar responsabilidades.\n\nComo líder atual, Ysara é respeitada por conhecer tanto a liturgia quanto a administração. Edras Fulgrim a trata com reverência cautelosa; Maelis pede dela recursos; Talia cobra respostas rápidas; Othran entrega-lhe listas intermináveis. Sua reputação popular é a de uma voz culta que escuta antes de mandar, virtude que consola alguns e irrita outros em tempo de cadáveres inquietos. Usa sempre um véu de linho sem bordado e carrega as chaves da Basílica presas por fio azul. Com a crise do Norte, coordena hospitais, cemitérios, escolas e caravanas de socorro, enquanto a Abadia Branca tenta falar ao reino sem rachar por dentro.",
  "ordem-dos-tres:calen-cera-negra":
    "Calen Cera-Negra nasceu em Ferrum, entre armazéns de peças rituais e contratos de transporte para a Torre de Véspera. Sua família fabricava lacres resistentes ao sal, usados por navios, cartórios e ordens religiosas. A magia entrou em sua vida quando um selo antigo, devolvido pelas Brumas dentro de uma caixa vazia, queimou sua mão sem deixar fogo. Levado à Ordem dos Três, foi formado por Oren Caldris na leitura de materiais e por Serath, Voz da Cinza, no respeito aos objetos que guardam memória. Ganhou o epíteto depois de conter um relicário rachado com cera negra, sal e sete testemunhas, evitando que todos na sala ouvissem a mesma voz desconhecida por horas.\n\nGuardião de Artefatos, Calen conhece cada cofre, nicho e sala selada da Torre de Véspera pelo som da chave. Oria confia nele durante exames de candidatos; Irmã Fea o acusa de tratar feridas como inventário quando um objeto machuca alguém; Veyra o consulta sobre peças ligadas às Brumas. O povo raramente o vê, mas mercadores de velas falam do mago robusto que compra cera sem pechinchar e jamais vira as costas para uma caixa fechada. Usa barba curta, anéis grossos e cheira a resina aquecida. Com a crise atual, revisa artefatos ligados ao Norte, ao Sino e a antigos funerais, enquanto a Torre recebe pedidos demais para respostas tão lentas.",
  "ordem-dos-tres:edran-folha-palida":
    "Edran Folha-Pálida nasceu gnomo nos Picos da Nuvem Eterna, entre salões baixos, pontes suspensas e ninhos que os Euralune tratam como vizinhos antigos. Ainda jovem encontrou uma águia gigante ferida por metal envenenado e permaneceu dias no solo, longe das rotas aéreas, alimentando a ave com as próprias reservas. A magia verde despertou nesse cuidado: a ferida fechou, mas Edran saiu do episódio com a pele mais pálida e uma paciência que muitos confundem com mansidão. Levado à Torre de Véspera, foi formado por curadores de vida, botânicos de Sahr e mestres que ensinavam a diferença entre crescimento e invasão. Ganhou renome ao recuperar um vale suspenso tomado por doença sem queimar a floresta inteira.\n\nComo Guardião das Raízes, Edran é arquimago da Refração Verde e conselheiro incômodo para agricultores, caçadores e senhores que tratam terra como cofre. Maera e Ilyon o procuram em assuntos de sobrevivência; Fea aprendeu com ele a ouvir um corpo antes de fechá-lo; Solenne registra suas denúncias contra abusos nos campos e rios. Camponeses o respeitam quando as pragas chegam, embora alguns nobres o chamem de obstáculo pequeno e teimoso. Carrega sementes em tubos de osso, anda descalço sempre que o chão permite e fala baixo até diante de insultos. Na crise atual, deixou os Picos para examinar colheitas frias, animais inquietos e sinais de que a morte do Norte começa a tocar raízes longe das geleiras.",
  "ordem-dos-tres:ilyon":
    "Ilyon, Voz do Sangue, é a face mais lembrada pelos iniciados que sobreviveram a ritos difíceis no corpo de Maelor Véspera. Sua origem pública pertence ao próprio mistério do Trino: a Ordem registra Maelor como nascido no Vale da Coroa, mas reconhece Ilyon como voz plena desde a investidura em que o corpo saiu do círculo branco com três assinaturas rituais. A formação atribuída a Ilyon passa pelas enfermarias da Torre, pelos tratados de juramento e pelas campanhas em que a Ordem acompanha soldados feridos. Muitos o conheceram durante um desabamento ritual, quando manteve três aprendizes conscientes até que Maera Vhal chegasse com curadores.\n\nComo comandante e curador, Ilyon conduz proteções de corpo, transferência de dor e reforço de patrulhas expostas a frio ou medo. Maera o respeita pela coragem prática; Irmã Fea discute com ele quando a urgência atropela repouso; Edran o chama de irmão de ofício; Serath registra o que ele preferiria resolver com as mãos. Entre servos da Torre, é a voz do Trino que pergunta nomes antes de cargos. Quando Ilyon domina a fala, o corpo de Maelor inclina-se para a pessoa ferida, e a mão direita fecha como quem mede pulso. Na crise atual, organiza curadores arcanos para Stonebridge, Abadia Branca e qualquer coluna que siga rumo ao Norte.",
  "ordem-dos-tres:irma-fea-do-circulo":
    "Irmã Fea do Círculo nasceu em Abadia Branca, filha de uma enfermeira leiga e de um pedreiro que consertava muros de cemitério. Cresceu entre a Ordem do Sino e histórias sobre magos que chegavam tarde demais aos hospitais. O talento apareceu quando ela, sem treinamento, fechou a hemorragia de um aprendiz esmagado por uma pedra funerária, pagando com uma febre que durou nove dias. A Ordem dos Três a levou à Torre de Véspera, onde Maera Vhal lhe ensinou cura vermelha e Edran Folha-Pálida a disciplina de não confundir vida com posse. Seu nome ganhou peso depois de salvar cinco iniciados de um círculo mal traçado e, diante do Conselho, descrever cada erro sem poupar mestre algum.\n\nComo curadora e crítica, Fea assiste candidatos após ritos, registra sequelas e questiona protocolos que outros preferem chamar de tradição. Oria a considera incômoda e indispensável; Calen recebe dela relatórios manchados de sangue; Ilyon a trata com respeito afetuoso; Solenne aprecia sua precisão quando acusa. Fora da Torre, famílias de iniciados a veem como a pessoa que entrega notícias sem esconder dor atrás de cerimônia. É baixa, tem mãos sempre aquecidas por faixas de lã e desenha círculos no chão antes de falar sobre qualquer ferimento sério. Na crise atual, prepara enfermarias arcanas para sobreviventes vindos do Norte e para jovens chamados cedo demais ao serviço da Ordem.",
  "ordem-dos-tres:maelor-vespera":
    "Maelor Véspera nasceu no Vale da Coroa, numa família de administradores menores ligada a medições de estrada e custódia de selos reais. Foi levado à Torre de Véspera ainda adolescente, depois de resolver uma disputa de limites desenhando três versões corretas do mesmo caminho. A Ordem reconheceu nele uma aptidão rara para suportar contradições rituais sem quebrar o círculo. Seus mestres vieram de várias Refrações: Solenne Arct ensinou-lhe juramentos, Nymor Sahr os perigos da percepção, Vaelis Morcant o trato com passagens e Maera Vhal o peso de manter alguém vivo quando todos aguardam uma sentença. Tornou-se Maelor Véspera, o Trino, após o rito que uniu no mesmo corpo Serath, Ilyon e Veyra.\n\nHoje governa a Ordem dos Três com fala calma, gestos econômicos e uma autoridade que nunca parece precisar de pressa. O Conselho das Sete Refrações limita e sustenta seu poder; Oria, Calen e Fea lidam com as consequências diárias de suas decisões. Nobres o procuram como conselheiro arcano, sacerdotes o vigiam com cautela e o povo o descreve como três sombras dentro de um homem educado. Usa túnica branca quebrada por fios sem cor definida e escreve com a mão esquerda quando registra decisões do Trino. Na crise atual, Maelor se divide entre a Torre, o Vale da Coroa e os chamados da Regência, tentando manter a Ordem útil sem permitir que pânico político transforme magia em decreto.",
  "ordem-dos-tres:maera-vhal":
    "Maera Vhal nasceu nas Marcas do Norte, numa aldeia Vargen pequena demais para aparecer em mapas da Coroa. A infância foi feita de lenha contada, sopa rala e nomes gravados em tábuas quando a terra não cedia ao enterro. A magia entrou em sua vida numa noite de frio extremo, quando manteve o irmão vivo com sangue, cobertor e uma prece que nenhum sacerdote havia ensinado. A Ordem dos Três a encontrou depois, por meio de curadores do Sino que reconheceram marcas de Refração Vermelha. Foi formada na Torre por mestres severos de sangue e juramento, mas conservou o modo nortista de medir palavras pelo que elas suportam no inverno.\n\nComo Mãe Rubra, Maera é uma das Grandes Arquimagas mais respeitadas e menos confortável nos salões nobres. Ensina resistência, transferência de dor e pactos familiares; Ilyon se aproxima de seus métodos, Oria a consulta sobre candidatos fortes demais para o próprio corpo, e Solenne discute com ela quando urgência e verdade seguem ritmos diferentes. Soldados a veneram, camponeses a chamam quando a hemorragia não espera, e nobres a recebem com cautela. Sua mão esquerda permanece enluvada, e ela testa a temperatura da água com a direita. Na crise atual, percorre as rotas entre Marcas do Norte, Stonebridge e a Torre, preparando patrulhas e enfermarias para um inverno que já chegou cobrando nomes.",
  "ordem-dos-tres:mestra-oria-sem-nome":
    "Oria chegou à Torre de Véspera sem sobrenome aceito, conduzida por dois guardas reais e por uma carta lacrada da própria Ordem dos Três. Os registros públicos dizem apenas que nasceu em alguma vila do Vale da Coroa, perto da Estrada das Brumas, e que sobreviveu a um surto de sonhos compartilhados durante a infância. Foi formada por Nymor Sahr nas leituras de presságio e por Solenne Arct na disciplina dos juramentos, combinação que fez dela uma examinadora temida. Seu nome se tornou conhecido quando recusou três candidatos indicados por Casas poderosas e aprovou, no mesmo rito, uma órfã de escribas que hoje serve nos círculos de selagem.\n\nResponsável pelos Candidatos ao Rito, Oria vigia cada sinal de talento como quem mede uma febre. Fala em períodos longos, cita fracassos antigos da Ordem e raramente responde à primeira pergunta que lhe fazem. Maera Vhal a considera dura com jovens feridos; Calen Cera-Negra confia em sua capacidade de perceber mentiras nos corredores; Irmã Fea a enfrenta quando os testes deixam marcas demais. Entre o povo, Oria é lembrada como a mulher sem nome que decide quais nomes podem tocar magia. Na crise atual, permanece na Torre de Véspera, revendo listas de iniciados e interrogando qualquer relato de poder novo vindo do Norte ou de Asterhall.",
  "ordem-dos-tres:serath":
    "Serath, Voz da Cinza, é conhecido publicamente como uma das três vozes do corpo de Maelor Véspera, o Trino da Ordem dos Três. Os cronistas da Torre dizem que sua presença foi reconhecida durante o último rito de investidura, quando o corpo de Maelor leu, sem pausa, inscrições funerárias em quatro línguas e corrigiu um erro cometido havia setenta anos nos arquivos de uma ruína do Vale da Coroa. A tradição da Ordem não trata Serath como fantasma nem como mero hábito mental, mas como voz juramentada, capaz de conduzir selos, estudos de mortos e exames de objetos que preservam memória.\n\nHistoriador e estrategista, Serath formou gerações de copistas arcanos na paciência dos vestígios. Vaelis Morcant e Calen Cera-Negra o procuram quando relíquias respondem a nomes antigos; Oria usa suas anotações para ensinar candidatos a não tocar o que não compreendem; Ilyon, no mesmo corpo, costuma tornar suas decisões mais suportáveis para iniciados. O povo comum raramente distingue o Trino por voz, mas guardas da Torre dizem que Serath fala baixo, não pisca diante de cadáveres e apoia dois dedos na têmpora antes de responder. Na crise atual, é a voz mais ouvida nos levantamentos de Rimewatch, nos mapas de cemitérios violados e nas perguntas que a Coroa preferiria ver tratadas como boato.",
  "ordem-dos-tres:solenne-arct":
    "Solenne Arct nasceu em Asterhall, numa casa de magistrados que ensinava crianças a distinguir testemunho, boato e conveniência antes mesmo da primeira aula de dança. Cresceu entre tribunais da Casa Valerius, copiando atas e ouvindo como uma frase correta podia salvar ou arruinar uma família. A magia apareceu quando, durante um julgamento, uma inscrição raspada brilhou sob sua mão e revelou uma cláusula omitida. A Ordem dos Três a levou à Torre de Véspera, onde estudou a Refração Amarela, os contratos mágicos e os preços da verdade dita fora de hora. Seu nome se firmou ao autenticar uma sucessão disputada sem favorecer a Coroa nem a Casa acusadora, decisão que lhe rendeu inimigos elegantes.\n\nComo Voz do Meio-Dia, Solenne ocupa a Cadeira Amarela com disciplina quase judicial. Valida tratados, investiga juramentos e ilumina presenças ocultas em conselhos fechados. Oria aprendeu com ela a interrogar candidatos; Veyra a inquieta por falar em símbolos; Maelor a chama quando a Regência precisa de palavras que resistam a magia e política. O povo comum a imagina como luz que queima mentiroso, exagero que ela nunca desmente. Usa colarinho alto, luvas claras e uma pena de ouro sem tinta até o momento de assinar. Na crise atual, está em Asterhall, perto de audiências, acusações e documentos da coroação antecipada, examinando cada promessa feita enquanto o Norte desaparece nas notícias.",
  "ordem-dos-tres:veyra":
    "Veyra, Voz do Véu, é a mais silenciosa das três vozes reconhecidas no corpo de Maelor Véspera. A Ordem dos Três afirma que ela se manifestou durante uma noite de Bruma ao redor da Torre de Véspera, quando o corpo do Trino acordou falando de portas que ninguém havia aberto e descreveu, com exatidão desconfortável, sonhos sonhados por candidatos em alas diferentes. Sua formação pública é associada aos estudos de Nymor Sahr, aos mapas de Cassia Mareth e às práticas de observação das Brumas. O episódio que fixou sua reputação ocorreu quando orientou uma caravana perdida na Estrada das Brumas sem sair da Torre, usando apenas relatos de sono, sal molhado e sinos ouvidos ao longe.\n\nProfetisa e sonhadora, Veyra interpreta presságios, presenças ocultas e caminhos impossíveis. Oria a consulta antes de ritos de candidatos marcados por sonhos; Calen lhe entrega objetos devolvidos pela névoa; Solenne desconfia de respostas que não cabem em ata; Serath registra suas palavras com cuidado excessivo. Para o povo, Veyra é quase rumor: uma voz do Trino que fala pouco e faz janelas parecerem mais profundas. Quando ela assume, Maelor evita luz direta e passa o polegar sobre a borda de um copo vazio. Na crise atual, observa relatos de constelações erradas, cadáveres que seguem chamados e Brumas entrando em estradas onde não deveriam estar.",
};

/** A biografia de um NPC, ou string vazia quando ainda não foi autorada. */
export function biographyFor(affiliation: string, id: string): string {
  return NPC_BIOGRAPHIES[`${affiliation}:${id}`] ?? "";
}
